quests[13703] = { id = 13703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Eisenschmiede", description = "Seid willkommen, Champion. Ich habe schon von Euren Kampffertigkeiten gehört. Wollt Ihr der Turniersdelegation von Eisenschmiede beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion von Eisenschmiede ernannt hat, wird Euer Knappe unser Banner in die Schlacht tragen dürfen.", sourceObjective = "Sprecht wieder mit Lana Starkhammer, falls Ihr ein Recke von Eisenschmiede werden wollt.", completion = "Wir sind stolz, dass Ihr Euch dazu entschlossen habt, uns beizutreten, und ich weiß, dass Ihr auf dem Schlachtfeld glänzen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13704] = { id = 13704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Gnomeregan", description = "Seid willkommen, Champion. Ich habe schon von Euren Kampffertigkeiten gehört. Gnomeregans Delegation könnte von jemandem wie Euch wirklich profitieren.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Gnomeregan ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Ambrose Bolzenfunk, falls Ihr ein Recke von Gnomeregan werden wollt.", completion = "Wir sind stolz, Euch unter uns zählen zu dürfen, {name}, und wir freuen uns darauf, mit Euch zu trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13705] = { id = 13705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke der Exodar", description = "Seid willkommen, Champion. Ich habe schon von Euren Heldentaten gehört. Wollt Ihr der Turniersdelegation der Exodar beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion der Exodar ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Kolosos, falls Ihr ein Recke der Exodar werden wollt.", completion = "Es ist gut, dass Ihr nun zu uns gehört, {name}. Wir werden alle vom Training mit Euch profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13706] = { id = 13706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Darnassus", description = "Seid willkommen, Champion. Ich habe von Euren Leistungen gehört und wir wären geehrt, wenn Ihr der Delegation von Darnassus beitreten würdet.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Darnassus ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Jaelyne Abendlied, falls Ihr ein Recke von Darnassus werden wollt.", completion = "Die Krieger von Darnassus sind geehrt, an Eurer Seite kämpfen und trainieren zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13707] = { id = 13707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Orgrimmar", description = "Ihr seid also ein Champion geworden? Dann habt Ihr Euch als würdiger Kämpfer erwiesen und ich wäre stolz, Euch in Orgrimmars Delegation begrüßen zu dürfen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hochklettern, doch sobald man Euch zum Champion von Orgrimmar ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Mokra dem Schädelberster, falls Ihr ein Recke von Orgrimmar werden wollt.", completion = "Dann seid willkommen, {name}. Ich freue mich darauf, Euch beim Training mit meinen Männern zuzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13708] = { id = 13708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Sen'jin", description = "Grüße, Champion. Wenn Ihr wollt, dann würde ich Euch in Sen'jins Turniersdelegation willkommen heißen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hochklettern, doch sobald man Euch zum Champion von Sen'jin ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Zul'tore, falls Ihr ein Recke von Sen'jin werden wollt.", completion = "Ich bin froh, dass Ihr Euch dazu entschlossen habt, uns beizutreten, und freue mich darauf, Euch in Aktion zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13709] = { id = 13709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Donnerfels", description = "Willkommen, Champion. Als Großchampion der Delegation von Donnerfels wäre ich stolz darauf, Euch in unseren Reihen begrüßen zu dürfen, falls Ihr dies wünscht.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Donnerfels ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Runok Wildmähne, falls Ihr ein Recke von Donnerfels werden wollt.", completion = "Es ehrt mich, dass Ihr Euch dazu entschlossen habt, unserer Delegation beizutreten. Ich weiß, dass Ihr uns stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13710] = { id = 13710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Unterstadt", description = "Seid willkommen, Champion. Die Delegation der Verlassenen könnte immer so jemanden wie Euch gebrauchen. Wollt Ihr uns beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Unterstadt ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Todespirscher Visceri, falls Ihr ein Recke von Unterstadt werden wollt.", completion = "Ihr habt eine weise Entscheidung getroffen, {name}. Wir beide werden von dieser Abmachung profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13711] = { id = 13711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Silbermond", description = "Ihr seid also ein Champion geworden? Dann habt Ihr Euch als würdiger Kämpfer erwiesen und ich wäre stolz, Euch in Silbermonds Delegation begrüßen zu dürfen.\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch sobald man Euch zum Champion von Silbermond ernannt hat, wird Euer Grunzling die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Eressea Morgensänger, falls Ihr ein Recke von Silbermond werden wollt.", completion = "Es wird uns eine Ehre sein, mit Euch zu trainieren und am Wettkampf teilzunehmen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13713] = { id = 13713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen von Eisenschmiede beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, für unsere Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Lana Starkhammer beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen von Eisenschmiede auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13714] = { id = 13714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wappen des Recken", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", sourceObjective = "Bringt 25 Siegel des Recken zu Lana Starkhammer beim Argentumturnierplatz.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13715] = { id = 13715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wappen des Recken", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", sourceObjective = "Bringt 25 Siegel des Recken zu Ambrose Bolzenfunk beim Argentumturnierplatz.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", sourceObjectiveStatus = "unverified-source-field" }
