quests[13721] = { id = 13721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wappen des Recken", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", sourceObjective = "Bringt 25 Siegel des Recken zu Todespirscher Visceri beim Argentumturnierplatz.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13722] = { id = 13722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wappen des Recken", description = "In Eurer Ausbildung zum Recken habt Ihr die Möglichkeit, Euer Können gegen Recken der anderen Städte auf die Probe zu stellen. Obwohl diese Kämpfe nicht zum formalen Teil des Wettkampfes gehören, werdet Ihr wertvolle Lektionen in Sachen Kampfstil erhalten und Schwächen Eurer Widersacher entdecken.\n\nRecken sind ein beherzter Haufen - sie konkurrieren untereinander um Ehre und Ruf.\n\nFührt Eure Ausbildung so lange fort, bis Ihr von Eurem Können überzeugt seid und all Eure Gegner schlagen könnt, um mir dann die Siegel zu bringen, die Ihr errungen habt.", sourceObjective = "Bringt 25 Siegel des Recken zu Eressea Morgensänger beim Argentumturnierplatz.", progress = "Seid Ihr bereit zu zeigen, wie gut Ihr die Fähigkeiten des Recken beherrscht?", completion = "Beeindruckend, Recke. Ich werde die Vorbereitungen für Eure Prüfung umgehend treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13723] = { id = 13723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen Gnomeregans beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Ambrose Bolzenfunk beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen von Gnomeregan auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13724] = { id = 13724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen der Exodar beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Kolosos beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen der Exodar auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13725] = { id = 13725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, im Namen Darnassus beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr würdig seid, im Namen unserer Stadt in die Listen aufgenommen zu werden, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Übungsring der Recken am westlichen Rand des Platzes. Er wird Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Jaelyne Abendlied beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet im Namen von Darnassus auf der höchsten Stufe des Turniers antreten und im großen Arenakampf reiten, Eure Waffe bereit und Eure beeindruckende Standarte im Rücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13726] = { id = 13726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Mokra dem Schädelberster beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner Orgrimmars die Konkurrenz vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13727] = { id = 13727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Zul'tore beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner der Dunkelspeere die Konkurrenz vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13728] = { id = 13728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Runok Wildmähne beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr den Argentumchampion bezwungen?", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner von Donnerfels die Konkurrenz vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13729] = { id = 13729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Todespirscher Visceri beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr den Argentumchampion bezwungen?", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner von Unterstadt die Konkurrenz vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13731] = { id = 13731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Recken", description = "Ihr seid fast bereit, beim großen Arenakampf anzutreten. Um zu beweisen, dass Ihr dieser Ehre würdig seid, müsst Ihr einen Champion des Argentumkreuzzugs besiegen.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und sattelt auf. Sprecht dann mit Knappe Danny im Ring der Recken des Argentumkreuzzugs am westlichen Rand des Platzes. Er wird dann Euren Gegner herbeirufen, sobald Ihr bereit seid.\n\nNachdem der Kampf entschieden ist, werden wir uns über das Resultat unterhalten.", sourceObjective = "Sprecht mit Knappe Danny, um Euren Gegner herbeizurufen. Kehrt zu Eressea Morgensänger beim Argentumturnierplatz zurück, sobald Ihr den Argentumchampion besiegt habt.\n\nLanzen gibt es auf jedem Lanzenständer in der angebundenen Nähe der Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", completion = "Ihr habt Euch für den Titel des Champions als würdig erwiesen, {name}. Ihr werdet auf der höchsten Stufe des Turniers antreten, im großen Arenakampf reiten und unter dem Banner von Silbermond die Konkurrenz vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13732] = { id = 13732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Herzlichen Glückwunsch, {name}. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz möchte mit Euch sprechen, {name}, und Euch offiziell beim großen Arenakampf anmelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13733] = { id = 13733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Herzlichen Glückwunsch, {name}. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13734] = { id = 13734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Herzlichen Glückwunsch, {name}. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer anderen Allianzstadt zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13735] = { id = 13735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Herzlichen Glückwunsch, {name}. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer anderen Allianzstadt zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13736] = { id = 13736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Ihr habt Euch meinen und den Respekt jener verdient, die Euch gleichgestellt sind; habt all Eure Herausforderer besiegt und beherrscht nun die Kunst des Turnierkampfes. Ihr seid zweifellos dazu bereit, für die Ehre Orgrimmars den Champions der anderen Städte ins Auge zu blicken!\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer unserer anderen Städte zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13737] = { id = 13737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Ihr habt Euch meinen und den Respekt jener verdient, die Euch gleichgestellt sind; habt all Eure Herausforderer besiegt und beherrscht nun die Kunst des Turnierkampfes. Ihr seid zweifellos dazu bereit, für die Ehre der Dunkelspeere den Champions der anderen Städte ins Auge zu blicken!\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer unserer anderen Städte zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13738] = { id = 13738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Ihr habt Euch meinen und den Respekt jener verdient, die Euch gleichgestellt sind; habt all Eure Herausforderer besiegt und beherrscht nun die Kunst des Turnierkampfes. Ihr seid zweifellos dazu bereit, für die Ehre von Donnerfels den Champions der anderen Städte ins Auge zu blicken!\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer unserer anderen Städte zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13739] = { id = 13739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Ihr habt Euch meinen und den Respekt jener verdient, die Euch gleichgestellt sind; habt all Eure Herausforderer besiegt und beherrscht nun die Kunst des Turnierkampfes. Ihr seid zweifellos dazu bereit, für die Ehre der Verlassenen den Champions der anderen Städte ins Auge zu blicken!\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13740] = { id = 13740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg eines Champions", description = "Ihr habt Euch meinen und den Respekt der Euch gleichgestellten verdient, habt all Eure Herausforderer besiegt und beherrscht nun die Kunst des Turnierkampfes. Ihr seid zweifellos dazu bereit, für die Ehre Silbermonds den Champions der anderen Städte ins Auge zu blicken!\n\nJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, {name}, und Euch offiziell beim großen Arenakampf der Champions anzumelden.", sourceObjective = "Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.", completion = "Ich heiße Euch als einen der Champions des Turniers willkommen, {name}. Ihr werdet um den Großmeistertitel des Turniers kämpfen können. Außerdem habt Ihr die Wahl, ein Recke der Delegation einer unserer anderen Städte zu werden und mit der Zeit auch einer ihrer Champions.\n\nAlle Champions müssen von einem Knappen unterstützt werden, {name}, Ihr mit eingeschlossen. Erlaubt mir, einen der unsrigen zu Eurem Knappen zu machen, um Euch im Kampf zur Seite zu stehen. Er wird mit Stolz das Banner jeder Stadt tragen, die Euch zum Champion ernannt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13741] = { id = 13741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln, die eine mächtige Klinge bewachte. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, sodass die Klinge nimmermehr gezogen werden könnte. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Lana Starkhammer beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13742] = { id = 13742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierwaffe verloren und dabei brauche ich sie doch in der Partie heute Nachmittag.\n\nEiner der Barden hat mir erzählt, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Drak'Marsee in der nordöstlichen Drachenöde nahe der Grenze zu Zul'Drak und den Grizzlyhügeln.", sourceObjective = "Bringt Lana Starkhammer beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "<Der Großchampion nimmt die Klinge von Drak'Mar entgegen.>\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13743] = { id = 13743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Lana Starkhammer beim Argentumturnierplatz möchte, dass Ihr ihr die Winterschneide beschafft.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13744] = { id = 13744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Rollo Immertreff beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Es ist gut, wenn wir uns daran erinnern, dass die Geißel noch immer da draußen ist, selbst während wir für den Wettkampf trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13745] = { id = 13745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger von Eisenschmiede freuen sich auf die Nachricht unseres Sieges - und damit diese auch eintrifft, haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut. Die Recken trainieren in einem Ring direkt neben unserem Zelt. Nehmt Eure Lanze, geht zu den Reittieren außerhalb des Pavillons, steigt auf den Widder aus Eisenschmiede, der dort steht, und fordert andere Allianzrecken heraus.", sourceObjective = "Bringt 3 Male des Recken zu Clara Torkelbräu beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr die Bürger von Eisenschmiede stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13746] = { id = 13746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Ambrose Bolzenfunk beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13747] = { id = 13747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierwaffe verloren und dabei brauche ich sie doch in der Partie heute Nachmittag.\n\nEiner der Barden hat mir erzählt, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Drak'Marsee in der nordöstlichen Drachenöde nahe der Grenze zu Zul'Drak und den Grizzlyhügeln.", sourceObjective = "Bringt Ambrose Bolzenfunk beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "<Ambrose nimmt die Klinge von Drak'Mar entgegen.>\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13748] = { id = 13748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Das ist das letzte Mal, dass ich mich mit einem Todesritter anlege.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Ambrose Bolzenfunk beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13749] = { id = 13749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Klack Radspanner beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Ich bin mir sicher, dass Ihr uns stolz machen werdet, wenn der Wettkampf anfängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13750] = { id = 13750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Wir wissen, wie sich alle darauf freuen, dass wir am Wettkampf mitmachen, und wir wollen sie nicht enttäuschen. Deswegen haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Turboschreiter, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Allianz gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Klick Radspanner beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr uns stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13752] = { id = 13752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Kolosos beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13753] = { id = 13753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierwaffe verloren und dabei brauche ich sie doch in der Partie heute Nachmittag.\n\nEiner der Barden hat mir erzählt, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Drak'Marsee in der nordöstlichen Drachenöde nahe der Grenze zu Zul'Drak und den Grizzlyhügeln.", sourceObjective = "Bringt Kolosos beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "<Der Großchampion nimmt die Klinge von Drak'Mar entgegen.>\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13754] = { id = 13754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Das ist das letzte Mal, dass ich mich mit einem Todesritter anlege.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Kolosos beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13755] = { id = 13755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Saandos beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Es ist gut, wenn wir uns daran erinnern, dass die Geißel noch immer da draußen ist, selbst während wir für den Wettkampf trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13756] = { id = 13756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger der Exodar freuen sich darauf zuzusehen, wie wir ihn gewinnen. Damit das auch geschieht, haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Azurmythoselekk, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Allianz gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Ranii beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr uns stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13757] = { id = 13757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Jaelyne Abendlied beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13758] = { id = 13758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierwaffe verloren und dabei brauche ich sie doch in der Partie heute Nachmittag.\n\nEiner der Barden hat mir erzählt, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Drak'Marsee in der nordöstlichen Drachenöde nahe der Grenze zu Zul'Drak und den Grizzlyhügeln.", sourceObjective = "Bringt Jaelyne Abendlied beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "<Jaelyne nimmt die Klinge von Drak'Mar entgegen.>\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13759] = { id = 13759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Das ist das letzte Mal, dass ich mich mit einem Todesritter anlege.\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon seit so langer Zeit bewacht, {name}.", sourceObjective = "Jaelyne Abendlied beim Argentumturnierplatz möchte, dass Ihr ihr die Winterschneide beschafft.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13760] = { id = 13760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Illestria Klingensänger beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Es ist gut, wenn wir uns daran erinnern, dass die Geißel noch immer da draußen ist, selbst während wir für den Wettkampf trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13761] = { id = 13761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger von Darnassus freuen sich darauf, zuzusehen, wie wir ihn gewinnen. Damit das auch geschieht, haben sie im Kampf gegen die Recken der anderen Allianzhauptstädte an ihren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nDer Ring der Recken der Allianz befindet sich direkt neben unserem Zelt. Geht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den darnassischen Nebelsäbler, der dort steht, und fordert die Recken heraus.", sourceObjective = "Bringt 3 Male des Recken zu Airae Sternensucher beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr Darnassus stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13762] = { id = 13762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Mokra dem Schädelberster beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13763] = { id = 13763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierwaffe verloren und dabei brauche ich sie doch in der Partie heute Nachmittag.\n\nEiner der Barden hat mir erzählt, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Drak'Marsee in der nordöstlichen Drachenöde nahe der Grenze zu Zul'Drak und den Grizzlyhügeln.", sourceObjective = "Bringt Mokra dem Schädelberster beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13764] = { id = 13764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Mokra der Schädelberster beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13765] = { id = 13765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Akinos beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Ich bin mir sicher, dass Ihr uns stolz machen werdet, wenn der Wettkampf anfängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13767] = { id = 13767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Wolf aus Orgrimmar, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Morah Worgschwester beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13768] = { id = 13768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Zul'tore beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13769] = { id = 13769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierwaffe verloren und dabei brauche ich sie doch in der Partie heute Nachmittag.\n\nEiner der Barden hat mir erzählt, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Drak'Marsee in der nordöstlichen Drachenöde nahe der Grenze zu Zul'Drak und den Grizzlyhügeln.", sourceObjective = "Bringt Zul'tore beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13770] = { id = 13770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Zul'tore beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13771] = { id = 13771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Schattenjäger Mezil-kree beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Ich bin mir sicher, dass Ihr uns stolz machen werdet, wenn der Wettkampf anfängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13772] = { id = 13772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Raptor der Dunkelspeere, der dort steht, und fordert die Recken heraus. Sie warten auf Euch im Ring der Recken der Horde gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Gahju beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Durch das Training mit den anderen Recken werdet Ihr Euch schnell das notwendige Wissen aneignen, mit dem Ihr sie schlagen könnt. Macht weiter so und Ihr werdet keine Probleme damit haben, sie im Wettkampf zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13773] = { id = 13773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Runok Wildmähne beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", sourceObjectiveStatus = "unverified-source-field" }
