quests[13780] = { id = 13780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Todespirscher Visceri beim Argentumturnierplatz möchte, dass Ihr ihm Winterschneide bringt.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13781] = { id = 13781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Sarah Chalke beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Einen ganzen Tag zu trainieren kann nie schaden. Gut zu sehen, dass Ihr in Übung bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13782] = { id = 13782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Kampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillon, nehmt Eure Lanze, steigt auf das Schlachtross der Verlassenen, das dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Tierführer Dretch beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13783] = { id = 13783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Ich habe gehört, dass die Champions der Allianz auf der Suche nach uralten Klingen für ihre Krieger sind. Wir können es uns nicht leisten, ihnen solch einen Vorteil zu überlassen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Eressea Morgensänger beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Die Geschichten stimmen also? Mit dieser Klinge sollten wir alles besiegen können, was die Teilnehmer der Allianz aufzubieten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13784] = { id = 13784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierwaffe verloren und dabei brauche ich sie doch in der Partie heute Nachmittag.\n\nEiner der Barden hat mir erzählt, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Drak'Marsee in der nordöstlichen Drachenöde nahe der Grenze zu Zul'Drak und den Grizzlyhügeln.", sourceObjective = "Bringt Eressea Morgensänger beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "Eine gute Waffe. Sie wird mir dabei helfen, meine Rivalen zu vernichten. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13785] = { id = 13785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Eressea Morgensänger beim Argentumturnierplatz möchte, dass Ihr ihr Winterschneide bringt.", progress = "Habt Ihr die Klinge ergattert?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13786] = { id = 13786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Kethiel Sonnenlanze beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Einen ganzen Tag zu trainieren kann nie schaden. Gut zu sehen, dass Ihr in Übung bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13787] = { id = 13787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Der Sieg wird nicht leicht zu erringen sein, doch ich bin überzeugt, dass wir gewinnen werden. Ihr müsst so lange mit Eurem Reittier trainieren, bis Ihr eins mit ihm seid.\n\nEs wird helfen, Euch auf die Härte des Turnierkampfes vorzubereiten.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf den Falkenschreiter von Silbermond, der dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Horde gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Aneera Thuron beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Mit den anderen Recken zu trainieren wird Eure Krallen und Euren Kampfinstinkt schärfen. Ihr werdet bereit sein, wenn der Wettkampf beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13788] = { id = 13788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher halt machen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.\n\nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.\n\nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar herum.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", completion = "{name}, Ihr habt das Turnier vor einem vernichtenden Angriff bewahrt. Der Argentumkreuzzug und all jene, die hier versammelt sind, stehen in Eurer Schuld und wir werden dafür sorgen, dass sie sich auch daran erinnern. Die Friedensbewahrer und Himmelsklauen machen so einen Wind darum, Schutz zu bieten, doch sie verbringen mehr Zeit damit, Schlägereien zwischen Betrunkenen aufzulösen, als uns vor der Geißel zu beschützen.\n\nMacht nichts - wir beschützen immer die unseren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13789] = { id = 13789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Das Kolosseum befindet sich im gefährlichsten Teil der Welt, {name}. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.", sourceObjective = "Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Anhänger des Kults der Verdammten im Bereich von Eiskrone.", completion = "Ihr seid ein wahrer Champion, {name}, im Ring und auf dem Schlachtfeld. Wir alle müssen wachsam gegenüber der Geißel sein und Ihr seid unseren Brüdern und Eurem eigenen Volke ein Beispiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13790] = { id = 13790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Diejenigen, die Ihr besiegt habt, werden bis zum Beginn des Turniers ihre Anstrengungen verdoppelt haben und danach trachten, ihren Verlust zu rächen, den sie durch Euch erfahren mussten.\n\nEs wäre Euch anzuraten, im Kampf mit den Streitern, die im Ring der Champions auf Euch warten, Eure Fähigkeiten zu verbessern. Nehmt Eure Lanze, geht zur Südseite des Platzes, besteigt eines der Euch zur Verfügung stehenden, angebundenen Reittiere und fordert sie heraus.", sourceObjective = "Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Gut gemacht. Mit den anderen Champions zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr die Allianz stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13791] = { id = 13791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur'thar und Todessprechers Wacht vertreten.", sourceObjective = "Zor'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", completion = "Ihr habt gute Arbeit dabei geleistet zu zeigen, dass wir unserer Verpflichtung nachkommen und die Geißel bekämpfen, egal wo wir sind oder was wir tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13793] = { id = 13793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen besiegt. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt irgendein Euch zur Verfügung stehendes Reittier aus und fordert sie heraus.", sourceObjective = "Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Ihr beherrscht den Umgang mit Eurem Reittier gut, {name}. Mit der Zeit werden Eure Gegner Euch fürchten lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13794] = { id = 13794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eadric der Reine", description = "Ich habe meine Brüder des Argentumkreuzzugs gebeten, eng mit denjenigen zusammenzuarbeiten, die zum Champion aufsteigen. Eadric der Reine, der Großchampion unserer Bruderschaft, hilft dabei, die Trainingsübungen für Champions aller Städte zu beaufsichtigen und sie bei ihren letzten Vorbereitungen für den Turnierwettkampf zu unterstützen.\n\nBitte geht nun und stellt Euch ihm vor. Ich bin mir sicher, dass er begierig darauf sein wird, Eure Bekanntschaft zu machen und Euch auf Eurem Weg zum Wettkampf mit Azeroths größten Champions zu begleiten.", sourceObjective = "Sprecht mit Eadric dem Reinen beim Argentumturnierplatz.", completion = "Gut, Euch endlich kennenzulernen, Champion. Der Hochlord hat mich gebeten, die Koordination der Champions in die Hand zu nehmen, um dafür zu sorgen, dass sie miteinander trainieren und die Verteidigung des Turnierplatzes verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13795] = { id = 13795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geißelbann", description = "Der Delegationsanführer der Ritter der Schwarzen Klinge hat darum gebeten, mit Euch zu sprechen, {class}. Crok Geißelbann ist ein äußerst furchterregender Kämpfer und ich hege keine Zweifel daran, dass er viel von Euch fordern wird.\n\nDie Ritter der Schwarzen Klinge haben auf der Nordseite des Turnierplatzes ihr Lager aufgeschlagen, westlich der Zeltbehausungen der Allianzdelegationen.", sourceObjective = "Sprecht mit Crok Geißelbann beim Argentumturnierplatz.", completion = "Ihr seid also ein Champion geworden, {name}. Ich hatte keine Zweifel daran, dass dies geschehen wird. Wir Ritter wurden in der Hitze des Kampfes ausgebildet, nicht an hölzernen Attrappen. Lasst uns den Paladinen und ihren Gästen zeigen, was die Schlacht aus uns gemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13809] = { id = 13809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Hochlord Tirion Fordring hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Seiner Meinung nach werden sie nicht aufhören, nur weil ihr Schwarzer Ritter besiegt wurde.\n\nUnsere Späher der Himmelsklauen haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll. Wenn wir sie nicht abfangen, werden sie das Turnier angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten und patrouilliert das Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", progress = "Habt Ihr den Stoßtrupp des Kults der Verdammten besiegt?", completion = "{name}, Ihr und Eure Verbündeten habt das Turnier vor einem vernichtenden Angriff bewahrt. Unsere Himmelsklauenreiter mögen zwar tapfer sein, haben jedoch alle Hände voll damit zu tun, den Frieden auf dem Turnierplatz zu wahren, und sie hätten Mühe damit, den Luftraum gegen die Angriffe des Kults zu verteidigen. Euch gehört der Dank des Argentumkreuzzugs und all derjenigen, die sich hier versammelt haben, um am Wettkampf teilzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13810] = { id = 13810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Das Kolosseum befindet sich im gefährlichsten Teil der Welt, {name}. Blut und Qualen waren der Preis, den wir bezahlen mussten, um dieses Gebiet der Geißel abzunehmen; trotzdem schlägt unser Gegner mit einer scheinbar unerschöpflichen Armee weiterhin zurück. Und was die Sache noch schlimmer macht, ist, dass diese untote Armee von sterblichen Sympathisanten unterstützt wird - dem Kult der Verdammten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, der Euch in die Quere kommt.", sourceObjective = "Cellian Tagesanbruch beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", completion = "Ihr seid ein wahrer Champion, {name}, im Ring und auf dem Schlachtfeld. Wir alle müssen wachsam gegenüber der Geißel sein und Ihr seid unseren Brüdern und Eurem eigenen Volke ein Beispiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13811] = { id = 13811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und von Euren Gegnern lernen. Champions aller Städte üben im Ring der Champions. Nehmt Eure Lanze, steigt auf irgendeins der angebundenen Reittiere, die Euch am Silberbundpavillon zur Verfügung stehen, und fordert sie heraus.", sourceObjective = "Bringt 4 Male des Champions zu Luuri beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Gut gemacht. Mit den anderen Champions zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr die Horde stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13812] = { id = 13812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "Der Argentumkreuzzug hat die Wachen verdoppelt, seitdem Ihr den Spitzel des Kults der Verdammten entlarvt habt. Man weiß dort, dass die Kultisten nicht eher halt machen werden, bis dieser Ort hier vernichtet und verhindert wurde, dass das Turnier stattfindet.\n\nDie Kundschafter des Argentumkreuzzugs haben davon berichtet, einen Frostwyrm namens Frostschlund gesichtet zu haben, der einen Stoßtrupp des Kults anführen soll.\n\nIhr müsst sie abfangen und beseitigen, bevor sie angreifen. Laut den Berichten der Späher fliegt Frostschlund gen Südwesten im Gebiet zwischen dem Eisenwallbollwerk und Aldur'thar herum.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr Frostschlund und 3 Kultistenbombenschützen besiegt.", completion = "{name}, Ihr habt das Turnier vor einem vernichtenden Angriff bewahrt. Der Argentumkreuzzug und all jene, die hier versammelt sind, stehen in Eurer Schuld und wir werden dafür sorgen, dass sie sich auch daran erinnern. Die Friedensbewahrer und Himmelsklauen machen so einen Wind darum, Schutz zu bieten, doch sie verbringen mehr Zeit damit, Schlägereien zwischen Betrunkenen aufzulösen, als uns vor der Geißel zu beschützen.\n\nMacht nichts - wir beschützen immer die unseren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13813] = { id = 13813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht zum Gegner tragen", description = "Es wird gut tun, bei all unseren Scheinkämpfen nicht zu vergessen, dass wir vom wahren Feind umgeben werden. Der Argentumkreuzzug möchte über einen Wettbewerb die besten Kämpfer ausfindig machen, doch das wäre schon mit denjenigen getan, die von der Schlacht zurückkehren. Lasst uns den Paladinen zeigen, dass wir willens sind, die Schlacht zum Kult der Verdammten zu tragen, selbst während wir uns auf das Turnier vorbereiten.\n\nGeht nach Eiskrone und tötet jeden Kultisten, dem Ihr begegnet. Sie sind besonders stark um Aldur'thar und Todessprechers Wacht vertreten.", sourceObjective = "Zor'be der Blutvergießer beim Argentumturnierplatz möchte, dass Ihr 15 Anhänger des Kults der Verdammten tötet. Dazu zählen alle Kultisten im Bereich von Eiskrone.", completion = "Ihr habt gute Arbeit dabei geleistet zu zeigen, dass wir unserer Verpflichtung nachkommen und die Geißel bekämpfen, egal wo wir sind oder was wir tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13814] = { id = 13814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Champions", description = "Als Champion habt Ihr die Kunst des berittenen Kampfes zur Vollendung gebracht, habt Herausforderer aller Klassen bezwungen. Ihr müsst Euch sicher sein, dass Ihr jeden besiegen könnt, dem Ihr auf dem Turnier entgegentreten werdet.\n\nIhr solltet weiterhin an Euren eigenen Fertigkeiten feilen und mehr über die Schwächen Eurer Gegner erfahren. Champions aller Städte üben im Ring der Champions in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon. Geht dorthin, nehmt Eure Lanze, wählt Euch irgendein zur Verfügung stehendes aus und fordert die Champions zu Übungskämpfen heraus.", sourceObjective = "Bringt 4 Male des Champions zu Illyrie Nachtlauer beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere oder im Sonnenhäscherpavillon, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training mit den anderen Champions beendet?", completion = "Ihr beherrscht den Umgang mit Eurem Reittier gut, {name}. Mit der Zeit werden Eure Gegner Euch fürchten lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13816] = { id = 13816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Das himmlische Planetarium", description = "Hört mal, <Kumpel/Mädel>! Das Schicksal von Azeroth steht hier auf dem Spiel.\n\nUnsere einzige Chance ist es, rechtzeitig das himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.\n\nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.", sourceObjective = "Ausgrabungsleiterin Loren im Archivum möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.", progress = "Habt Ihr ihn gefunden, {name}?", completion = "Verschlossen? Das war ja klar!\n\nIch werde Brann Bescheid sagen... vielleicht kann er etwas im Archivum entdecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13817] = { id = 13817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Datenscheibe des Archivums", description = "Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort \"ARCHIVUM\".\n\nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.", sourceObjective = "Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.", progress = "Die Konsole surrt vor Energie, als sich der runde Aufnahmebehälter öffnet.", completion = "Die Platinscheibe passt perfekt in die Konsole. Sie fängt an, sich zu drehen. Weiße Lichtstrahlen scheinen die darauf befindlichen Informationen abzutasten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13818] = { id = 13818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Algalon", description = "Ihr habt es wirklich geschafft, {name}. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum himmlischen Planetarium erhaltet.\n\nIhr beeilt Euch besser, <Kumpel/Mädchen>. Die Zeit drängt.", sourceObjective = "Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.", progress = "Die gleißenden Lichter der Konsole scannen mehrmals die Glasoberfläche, gerade so, als ob eine Form von Datenübermittlung erwartet würde.", completion = "Verifizierungsprozess läuft.\n\nZugang zum himmlischen Planetarium gewährt. Bitte Schlüssel entnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13819] = { id = 13819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Ende gut, alles gut", description = "Wir sollten uns jetzt besser beeilen, {name}. Wir müssen den Antwortcode von Dalaran aus übermitteln.\n\nBringt ihn zu Rhonin. Ich treffe Euch dort.", sourceObjective = "Überbringt Rhonin in Dalaran den Antwortcode Alpha.", progress = "Seid Ihr soweit, {name}?", completion = "Ihr seid hier. Lasst uns hoffen, dass das hier klappt. Um unser aller willen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13820] = { id = 13820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Sprengbolz", description = "Der Hochlord hat mich damit beauftragt, das Kolosseum so schnell wie möglich fertig zu stellen. Wir haben unsere Bauarbeiter an das Projekt gesetzt, aber wir mussten sehr schnell feststellen, dass wir Hilfe bei der Beschaffung von Materialien brauchten. Ich habe ein paar Goblins angeheuert, Stumpi Sprengbolz und seinen Bruder Stümpi.\n\nSie beaufsichtigen die Arbeiten am südöstlichen Ende des Turniergeländes. Sprecht mit Stumpi und findet heraus, ob er und sein Bruder noch weitere Hilfe dabei brauchen, das benötigte Baumaterial zu beschaffen.", sourceObjective = "Sprecht mit Stumpi Sprengbolz am Argentumturnierplatz.", completion = "Die Justiziarin hat Euch also geschickt? Gut, gut...\n\nWir können immer Hilfe brauchen bei der, äh, \"Anforderung\" von Materialien.", sourceObjectiveStatus = "unverified-source-field" }
quests[13821] = { id = 13821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Freyas Siegel", description = "Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.\n\nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.\n\nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.\n\nWas soll ich sagen, {name}, das ist eine ganz schöne Zwickmühle, in der wir da stecken.", sourceObjective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Freyas Siegel, {name}? Habt Ihr es?", completion = "Verdammt gute Arbeit, {name}. Wir sind unserem Ziel, Azeroth zu retten, einen Schritt näher!", sourceObjectiveStatus = "unverified-source-field" }
quests[13822] = { id = 13822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Hodirs Siegel", description = "Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!\n\nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!", sourceObjective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Konntet Ihr das Siegel bekommen, {name}?", completion = "Ihr habt es geschafft! Ich weiß nicht wie, aber Ihr habt es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[13823] = { id = 13823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Thorims Siegel", description = "Thorim ist nicht er selbst, {name}. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.\n\nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.\n\nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!\n\nIhr müsst ihn zur Vernunft bringen und zwar schnell.\n\nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.", sourceObjective = "Ausgrabungsleiterin Loren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Nun, {name}? Habt Ihr's?", completion = "Ihr werdet wohl nie aufhören, mich zu beeindrucken, {name}.\n\nIhr und ich sollten mal ein Bierchen trinken gehen, nachdem wir mit all dem hier durch sind. Mein Wort drauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[13824] = { id = 13824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Mimirons Siegel", description = "Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.\n\nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, um sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Konntet Ihr das Siegel an Euch bringen, {name}?", completion = "Das muss man Euch wirklich lassen, {name}. Unsere Chancen stehen vielleicht nicht zum Besten, aber wenn Ihr mit anpackt fühle ich mich gleich viel besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[13825] = { id = 13825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muschelette Surprise", sourceObjective = "Hey, ich erinnere mich an Euch! Seid Ihr nicht {name}? Ihr habt mir doch mal geholfen, das ganze Muschelette zu machen!\n\nIch sag Euch was: Kommt näher und ich zeige Euch mein neustes Rezept - es ist einfach und köstlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[13826] = { id = 13826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat Pagle, Extremangler", sourceObjective = "Na, aber hallo, {name}. Entweder lässt mein Gedächtnis mich langsam im Stich oder ich habe vergessen, Euch das hier zu geben, als wir uns das letzte Mal gesprochen haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[13828] = { id = 13828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Nahkampf beherrschen", description = "Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.", sourceObjective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet 5 Mal die Fähigkeit \"Zustoßen\" gegen ein Nahkampfziel an. Kehrt anschließend zu Arkanist Taelis beim Argentumturnierplatz zurück.", completion = "Behaltet die Worte des Meisters im Kopf, während Ihr mit den Übungsattrappen trainiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13829] = { id = 13829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Nahkampf beherrschen", description = "Der Mittelpunkt des Turnierwettkampfes ist der berittene Nahkampf. Nehmt diese Lanze und steigt auf den Falkenschreiter der Sonnenhäscher, der gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Jeran Waldesruh, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Jeran wird Euch beibringen, wie man sich im Nahkampf verteidigen kann.", sourceObjective = "Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Jeran Waldesruh und wendet 5 Mal die Fähigkeit \"Zustoßen\" auf ein Nahkampfziel an. Kehrt anschließend zu Magister Edien Sonnental beim Argentumturnierplatz zurück.", completion = "Behaltet die Worte des Meisters im Kopf, während Ihr mit den Übungsattrappen trainiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13830] = { id = 13830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geisterfisch", description = "Jeder Angler in Nordend, der sein Geld wert ist, weiß über den Pygmäenschiffshalter Bescheid. Er ist nicht essbar, manchmal jedoch für Alchemisten nützlich.\n\nEs gibt jedoch einen Fisch, einen etwas verstohleneren, der sich zwischen den Schiffshaltern im Flussnabel im Sholazarbecken versteckt: der Phantomgeisterfisch. Außerhalb des Wassers werden sie zunehmend lichtdurchlässig, bis sie schließlich ganz verschwinden. Einige nehmen an, dass sie nach Sholazar zurückkehren, andere wiederum sind etwas... abergläubischer.\n\nIch möchte, dass Ihr diesen Fisch fangt und um jeden Preis hinter sein Geheimnis kommt!", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr hinter das Geheimnis des Phantomgeisterfischs kommt.", completion = "Man wird also unsichtbar, wenn man ihn isst... was für eine seltsame Verteidigung dieser Fisch doch entwickelt hat.\n\nIch brauch ein Weilchen, um das zu verdauen - Wortspiel nicht beabsichtigt, {name}; wirklich. Wieso kommt Ihr nicht morgen wieder?", sourceObjectiveStatus = "unverified-source-field" }
quests[13832] = { id = 13832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perle der Kanalisation", description = "Schwer zu glauben, dass die meisten Leute, wenn sie zum Angeln in die Kanalisation von Dalaran gehen, nach Riesenratten und mutierten Fischen suchen. Besonders dann, wenn im Wasser Unmengen unbezahlbarer Juwelen zu finden sind - von gebrochenen Herzen, Dieben und achtlosen Trunkenbolden weggeworfen.\n\nDer Trick bei der Sache ist, Euren Haken am Boden entlang zu ziehen, und wenn Ihr etwas gefunden habt, beim Hochziehen nicht zu viel Kraft zu verwenden. Versucht es einmal, {name}. Ich wäre dazu bereit, was auch immer Ihr findet gegen ein paar meiner eigenen Schmuckstücke einzutauschen.", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr korrodierten Schmuck bringt.", progress = "Hattet Ihr Glück?", completion = "Also, das sieht aus, als könnte es wertvoll sein. Schwer zu sagen, bis es gesäubert und geschätzt wurde, aber ich bin noch immer dazu bereit, den Handel einzugehen, wenn Ihr es auch seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[13833] = { id = 13833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut ist dicker", description = "Der Blutzahnfrenzy ist ein quirliger kleiner Fisch, der für ein Rezept zur Heilung von infizierten Wunden verwendet wird. Wir könnten ein paar von ihnen gebrauchen, wenn Ihr helfen wollt.\n\nWie der Name schon sagt, trinken sie gerne Blut. Die einzige mir bekannte Art und Weise, die kleinen Teufel zu fangen, ist, Blut ins Wasser zu schütten und dann darin zu angeln.\n\nBeschmiert Euch also mit Blut... Tötet dazu einfach eine der Bestien in der boreanischen Tundra und springt anschließend ins Wasser. Ihr werdet im Nu den perfekten Köder haben.", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr 5 Blutzahnfrenzys bringt.", progress = "Irgendwelches Glück mit den Blutzahnfrenzys gehabt? Vergesst nicht, was ich Euch über das Blut gesagt habe.", completion = "Ihr seid mutig, {name}. Hoffe, dass Ihr beim Vorbereiten Eures Angelplatzes keine Gliedmaßen verloren habt. Wenn Ihr noch immer wild aufs Fischen seid, dann kommt morgen wieder und wir werden uns mehr darüber unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13834] = { id = 13834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährlich köstlich", description = "Die besten Angelplätze sind oft die gefährlichsten. Für diejenigen, die dreist genug sind, bietet sich Tausendwinter an - dort sind großzügige Fänge zu machen.\n\nGenau genommen ist es der einzige Ort, wo man den sagenhaften Schreckensfisch fangen kann - ein Fisch, tödlich und köstlich zugleich. Bringt mir ein paar und wir können weiterreden.", sourceObjective = "Marcia Balzer in Dalaran möchte, dass Ihr ihr 10 Schreckensfische bringt.", progress = "Seid auf der Hut, wenn Ihr hinter dem Schreckensfisch her seid.", completion = "Du meine Güte! Ihr habt Euch ein paar Schreckensfische gefangen. Das erinnert mich an die Zeit, als...\n\n<Marcia erinnert sich an Geschichten von Abenteuer und Fischfang und wird sie so lange erzählen, wie Ihr nur zuhören wollt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13835] = { id = 13835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schildbrecherangriff beherrschen", description = "Ihr werdet lernen müssen, wie man die Verteidigung Eures Gegners durchbrechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf das angebundene Streitross der Quel'dorei gleich außerhalb des Pavillons.\n\nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.", sourceObjective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Valis Windhetzer und wendet die Fähigkeit \"Schildbrecher\" gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.", progress = "Habt Ihr die Übungen mit dem \"Schildbrecher\" abgeschlossen?", completion = "Prägt Euch Valis' Lektionen ein, {name}. Es wird den Unterschied zwischen Sieg und Niederlage Eurer berittenen Kämpfe bedeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13836] = { id = 13836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arm dran, Arm ab!", description = "Ich habe von einem tragischen Zwischenfall im Gefängnis von Dalaran gehört; ein besonders brutaler Insasse hat einer Wache einen Arm abgerissen und ihn ins Wasser geworfen. Die Leute von der \"Ersten Hilfe\"-Station haben versprochen, dass sie den Arm wieder annähen können, falls wir ihn zurückbringen.\n\nIhr angelt einfach lange genug im Wasser vor der Violetten Festung, und ich verwette meine Lieblingsangelrute darauf, dass der Arm auftaucht. Findet ihn und bringt ihn zu Olisarra der Gütigen hier in Dalaran. Sie wird wissen, was zu tun ist.", sourceObjective = "Olisarra die Gütige in Dalaran möchte, dass Ihr ihr den abgetrennten Arm bringt.", progress = "Seid gegrüßt. Habt Ihr etwas für mich?", completion = "Oh, seid gegrüßt, {name}. Marcia hat gesagt, dass Ihr den fehlenden Arm des armen Kerls vorbeibringen würdet.\n\nAußerdem hat sie mir diese Tasche hier dagelassen, um sie Euch als Belohnung zu geben. Sie riecht scheußlich und ich kann es kaum erwarten, den Handel abzuschließen, falls Ihr nichts dagegen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13837] = { id = 13837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Ansturmangriff beherrschen", description = "Euer stärkster Angriff im berittenen Kampf ist zweifellos das \"Anstürmen\". Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist, und Euch ein paar grundlegende Strategien beibringen.", sourceObjective = "Nehmt Eure Lanze und steigt auf das abgestellte Streitross der Quel'dorei außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit \"Anstürmen\" gegen 2 ungeschützte Ansturmziele an. Kehrt anschließend zu Avareth Flinkstoß beim Argentumturnierplatz zurück.", progress = "Beherrscht Ihr nun das \"Anstürmen\"?", completion = "Mit etwas Erfahrung und Übung wird Euer Ansturm tödlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13838] = { id = 13838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schildbrecherangriff beherrschen", description = "Ihr werdet lernen müssen, wie man durch die Verteidigung Eures Gegners brechen kann, um im berittenen Kampf erfolgreich zu sein. Nehmt diese Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher gleich außerhalb des Pavillons.\n\nSprecht mit Valis Windhetzer, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Valis wird Euch die Grundlagen des Schildbrecherangriffs beibringen und wie man mit ihm ein Distanzziel verwundbar macht.", sourceObjective = "Nehmt Eure Lanze und steigt auf den abgestellten Falkenschreiter der Sonnenhäscher. Sprecht mit Valis Windhetzer und wendet die Fähigkeit \"Schildbrecher\" gegen 2 ungeschützte Distanzziele an. Kehrt anschließend zu Galathia Morgenglanz beim Argentumturnierplatz zurück.", progress = "Habt Ihr die Übungen mit dem \"Schildbrecher\" abgeschlossen?", completion = "Prägt Euch Valis' Lektionen ein, {name}. Es wird den Unterschied zwischen Sieg und Niederlage Eurer berittenen Kämpfe bedeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13839] = { id = 13839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Ansturmangriff beherrschen", description = "Euer stärkster Angriff im berittenen Kampf ist zweifellos das \"Anstürmen\". Nehmt diese Lanze und steigt auf das Streitross der Quel'dorei, das gleich außerhalb des Pavillons abgestellt ist.\n\nSprecht mit Rugan Stahlbauch, sobald Ihr erst einmal im Sattel sitzt. Er befindet sich am nördlichen Rand des Turnierplatzes im Trainingsbereich östlich des Rings der Streiter. Rugan wird Euch sagen, wie diese mächtige Fähigkeit zu verwenden ist, und Euch ein paar grundlegende Strategien beibringen.", sourceObjective = "Nehmt Eure Lanze und steigt auf den angebundenen Falkenschreiter der Sonnenhäscher außerhalb des Pavillons. Sprecht mit Rugan Stahlbauch und wendet die Fähigkeit \"Anstürmen\" gegen 2 ungeschützte Ansturmziele an. Kehrt anschließend zu Amariel Sonnenschwur beim Argentumturnierplatz zurück.", completion = "Mit etwas Erfahrung und Übung wird Euer Ansturm tödlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13845] = { id = 13845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelte Giftphiole", description = "Diese Giftphiole sieht besonders gefährlich aus. Womöglich könnte jemand in Dalaran daran interessiert sein.", sourceObjective = "Bringt die versiegelte Giftphiole zu Alchemist Cinesra in die Kanalisation von Dalaran.", progress = "Ist das, was ich denke, {class}?", completion = "Ihr seid mutig, das hier mit Euch herumgetragen zu haben. Wenn nur ein Tropfen auf Eure Haut gekommen wäre, hättet Ihr auf schmerzlichste Weise den Tod gefunden.\n\nErlaubt mir, Euch dafür zu entlohnen... Gift von außergewöhnlicher Stärke kann ich immer gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13846] = { id = 13846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Beitrag leisten", description = "Die besten der Champions kommen jeden Tag zur Kapelle, um der Argentumbeichtpatin zuzuhören.\n\nIhr solltet sehen, wie sehr sie von ihr inspiriert werden, {name}. Sie ziehen nicht nur für den Argentumkreuzzug in den Kampf, sondern geben auch noch sehr viel Geld in den Klingenbeutel, wenn ich ihn herumtrage.\n\nWollt Ihr womöglich auch einen Beitrag leisten?", sourceObjective = "Sprecht mit Knappe Artie, um einen Beitrag von 10 Gold an den Argentumkreuzzug zu leisten.", progress = "Wollt Ihr einen Beitrag leisten?", completion = "Habt Dank. Ich weiß einfach, dass es der Kreuzzug gut einsetzen wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[13847] = { id = 13847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Hauptmann Joseph Holley beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger mehr sind als bloße Dekoration für den Exerzierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13850] = { id = 13850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gifttoleranz", description = "Ihr wollt eine Gifthaut reiten? Dann hab' ich schlechte Neuigkeiten für Euch.\n\nDie Gifthautravasaurier, die bestehen aus nichts als Gift: giftiges Blut, giftiger Speichel, giftige Haut. Ihr steigt auf einen drauf und fallt nach ein paar Stunden tot runter.\n\nIhr müsstet zuerst gegen ihre Gifte resistent werden, bevor ich Euch einen verkaufe, und das dauert ganz schön lange... Ihr müsstet mit ihrem giftigem Blut bespritzt werden, wenn Ihr sie bekämpft. Und zwar sehr oft. Wenn Ihr wirklich daran interessiert seid: Die Gifthäute bevorzugen die nördliche Gegend der Marschen nordwestlich von hier.", sourceObjective = "Mor'vek im Krater von Un'Goro behauptet, dass wenn man 20-mal von dem Blut eines Gifthautravasauriers vergiftet wurde, auf einem reiten könnte, ohne zu sterben. Greift die Saurier an, um vielleicht vergiftet zu werden.", completion = "Ihr habt es geschafft? Ihr habt es wirklich geschafft?!\n\nHo ho! Dickköpfig wie meine Frau seid Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[13851] = { id = 13851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir die Vorbereitungen für das Turnier treffen, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Clara Torkelbräu beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir würdige Verbündete sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13852] = { id = 13852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Klick Radspanner beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit hat gezeigt, dass wir den Anhängern des Argentumkreuzzugs ebenbürtig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13854] = { id = 13854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Ranii beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger mehr sind als bloße Dekoration für den Exerzierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13855] = { id = 13855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Airae Sternensucher beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", progress = "Habt Ihr an der Seite der Kreuzfahrer im Hof der Knochen gedient?", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass sie sich im Kampf gegen den Lichkönig auf uns verlassen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13856] = { id = 13856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Morah Worgschwester beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat bestätigt, was die Kreuzfahrer ohnehin schon wussten: dass unsere Krieger die besten auf Azeroth sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13857] = { id = 13857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Gahju beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir angesichts der Diener des Lichkönigs keine Angst kennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13858] = { id = 13858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Anka Klauenhuf beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache un 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir loyale Verbündete im Kampf gegen den Lichkönig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13859] = { id = 13859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Aneera Thuron beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Eure Tapferkeit auf dem Feld hat den Kreuzfahrern gezeigt, dass wir bereit sind, jedem Gegner zu trotzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13860] = { id = 13860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor den Toren des Feindes", description = "Während wir uns auf das Turnier vorbereiten, bereitet der Argentumkreuzzug den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross, das im Lager untergebracht ist, und vernichtet die Diener des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Tierführer Dretch beim Argentumturnierplatz möchte, dass Ihr 15 Fußsoldaten der Knochenwache, 10 Späher der Knochenwache und 3 Leutnants der Knochenwache vernichtet.", completion = "Der Argentumkreuzzug hat gesehen, wie entschlossen wir sind, und sie wissen, dass unsere Krieger die Sache zu Ende bringen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13861] = { id = 13861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Es ermutigt uns vom Argentumkreuzzug, jemanden wie Euch zu haben, der Seite an Seite mit uns gegen den Lichkönig kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13862] = { id = 13862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während einige von uns auf dem Turnier alles geben, bereiten unsere Brüder den Weg für einen Angriff auf die Eiskronenzitadelle vor, die Hochburg des Feindes.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Eadric der Reine beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Es ermutigt uns vom Argentumkreuzzug, jemanden wie Euch zu haben, der Seite an Seite mit uns gegen den Lichkönig kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13863] = { id = 13863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während sich einige der Kreuzfahrer auf das Turnier vorbereiten, wurden andere ausgesandt, um die Hochburg des Feindes, die Eiskronenzitadelle, anzugreifen.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Wir sind nie vor der Geißel zurückgewichen, haben sie das Fürchten gelernt und diese Kampagne wird nicht anders sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13864] = { id = 13864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht vor der Zitadelle", description = "Während sich einige der Kreuzfahrer auf das Turnier vorbereiten, wurden andere ausgesandt, um die Hochburg des Feindes, die Eiskronenzitadelle, anzugreifen.\n\nIm Hof der Knochen im Südwesten der Eiskrone auf der Südseite von Corp'rethar haben ein paar mutige Kreuzfahrer ein Vorhutslager errichtet. Nehmt Eure Lanze, steigt auf das Argentumstreitross im Lager und vernichtet die Kommandanten des Lichkönigs.\n\nFürchtet nicht die Massen an Fußsoldaten der Knochenwache, {name}, denn sie können unter den Hufen Eures Pferds leicht zertrampelt werden.", sourceObjective = "Crok Geißelbann beim Argentumturnierplatz möchte, dass Ihr 3 Kommandanten der Knochenwache tötet.", completion = "Wir haben die Geißel an allen Fronten bekämpft, haben sie das Fürchten gelernt und diese Kampagne wird nicht anders sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13887] = { id = 13887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gifthauteier", description = "Jetzt, da Ihr gegen das Sauriergift immun geworden seid, könnt Ihr mit den Tieren und ihren Eiern sicher umgehen. Gifthäute sind ziemlich bösartig und müssen vom Moment des Schlüpfens an trainiert werden.\n\nWenn Ihr einen reiten wollt, dann werdet Ihr ein ungeschlüpftes Ei benötigen. In den gesamten Marschen verteilt gibt es einige Ravasauriernester. Sucht nach Eiern mit helleren Schalen - das sind diejenigen, aus denen später Gifthäute schlüpfen werden.\n\nWenn Ihr mir einige Eier bringt, werde ich Euch gestatten, eins zu behalten und unter meiner Aufsicht aufzuziehen.", sourceObjective = "Bringt Mor'vek im südöstlichen Teil der Marschen 4 Eier von Gifthautravasauriern.", progress = "Habt Ihr die Eier gefunden?", completion = "Gute Arbeit. Wirklich, ich bin erstaunt, dass Ihr so viele gefunden habt. Ihre Zahl scheint in jedem Gelege zurückgegangen zu sein.\n\nIch werde Euch einen der frisch geschlüpften Gifthäute aufziehen lassen. Er wird sich vermutlich nicht zieren, Euch wissen zu lassen, was er braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13889] = { id = 13889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sooooo hungrig", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen sind grob, aber Ihr könnt die Umrisse von Dimetrodonten, Stegodonten und Pterrordaktylen ausmachen. Als der Raptor die Zeichnung vervollständigt hat, sieht er wieder zu Euch auf, fletscht seine Zähne und schnappt ein paar Mal mit dem Maul.\n\nAnscheinend hat Euer Gifthautjunges Hunger auf frisches Fleisch von diesen Tieren. Findet und tötet Dimetrodonten, Stegodonten oder Pterrordaktylen im Krater von Un'Goro und füttert Euer hungriges Junges mit ihrem Fleisch.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 15 frische Dinosaurierfleischstücke an ihn verfüttert.", completion = "Das Gifthautjunge scheint mit der gewaltigen Mahlzeit, die Ihr ihm serviert habt, durchaus zufrieden. Es lässt sich allerdings schwer sagen, wann es wieder hungrig sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13903] = { id = 13903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorishigelee", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen des Jungen scheinen verschiedene Arten großer Insekten darzustellen, vielleicht die Gorishisilithiden. Das Junge beendet seine Zeichnung, zeigt mit einem kurzen Arm darauf, schnappt mit dem Kiefer und leckt sich das Mäulchen.\n\nEs möchte wohl, dass Ihr zur wuchernden Narbe, im Zentrum des südlichen Kraters von Un'goro geht und Silithidenfleisch sammelt. Wenn Ihr das Fleisch habt, gebt es Eurem hungrigen Jungen zu fressen.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 10 Stück Silithidenfleisch an ihn verfüttert.", completion = "Das Gifthautjunge grinst Euch mit spitzen Zähnen zufrieden an und rollt sich dann zum Schlafen zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13904] = { id = 13904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pochiert, gerührt oder roh?", description = "Der Magen des Gifthautjungen knurrt, als es mit seinen Ärmchen wedelt, um Eure Aufmerksamkeit zu bekommen. Es beginnt, die Umrisse von Silithiden in die Erde zu kratzen, darunter einige Ovale. Es sieht Euch hoffnugsvoll an und deutet auf die Kreise.\n\nSie können nur Silithideneier darstellen. Der giftige Unterschlupf im westlichen Tanaris, nahe der Grenze zum Krater von Un'goro, wäre sicherlich ein guter Ort, um die Eier zu finden, die Euer kleines Junges haben möchte.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 12 Silithideneier an ihn verfüttert.", completion = "Euer Junges leckt sich das Mäulchen, nachdem es die Riesenportion Silithideneier verschlungen hat. Für einen Moment glaubt Ihr, es sieht ein wenig enttäuscht aus, dass die Fütterungszeit schon vorbei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13905] = { id = 13905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sengende Rocfedern", description = "Das Junge sieht Euch für einen Moment an, ein wenig, also ob es sich fragt, ob Ihr verstehen werdet. Es kratzt ein Bild von einem Paar Federn in die Erde, bevor es mit einer Klaue auf die Lederbänder um seine Ellbogen und Knie zeigt.\n\nEs sieht nicht hungrig aus, aber wofür könnten die Federn gut sein?\n\nEs will sie wohl als Schmuck haben, wie Ihr ihn an den anderen Raptoren gesehen habt. Die größten Federn findet man bei den sengenden Rocs, welche die großen Tierknochen in der westlichen Tanariswüste umschwärmen, nordöstlich des Disteltals.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr ihm 5 Federn von sengenden Rocs bringt.", progress = "Euer Gifthautjunges sieht Euch erwartungsvoll an.", completion = "Das Gifthautjunge nimmt die Federn an sich und begutachtet sie, während es einige an seine Armbänder hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[13906] = { id = 13906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie werden so schnell erwachsen", description = "Durch Eure fachmännische Fütterung und Pflege wird Euer Gifthautjunges schnell heranwachsen. Im Laufe seines Wachstums werden seine ersten Zähne durch bleibende ersetzt. Solltet Ihr die Milchzähne aufbewahren, werdet Ihr mit Leichtigkeit sagen können, wann es ausgewachsen genug sein wird, um zugeritten zu werden.\n\nEuer Junges wird Euch wissen lassen, was es braucht - gebt also genau Acht. Bringt mir Euren kleinen Ravasaurus und die Materialien für Euren Sattel, wenn er all seine Zähnchen verloren hat, und ich werde mich um den Rest kümmern.", sourceObjective = "Bringt 20 Gifthautzähnchen, das Gifthautjunge, 20 Stück Runenstoff, 20 unverwüstliches Leder und 80 Gold zu Mor'vek im südöstlichen Teil des Marschlands im Krater von Un'Goro.", progress = "Habt Ihr gut auf den Raptor achtgegeben?", completion = "Sieht aus, als hättet Ihr die Aufzucht überstanden, ohne einander umzubringen.\n\nDa, alles ist fertig. Ich habe Euren Gifthautravasaurus so abgerichtet, dass er Euch folgt, wenn Ihr in diese Pfeife blast.\n\nNur wenige besitzen die nötige Hingabe, um einen der kleinen Ravasaurier per Hand großzuziehen, aber sie sind die Mühe auf jeden Fall wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13908] = { id = 13908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufsatteln", description = "Euer Ravasaurus ist stark und gesund, und Ihr habt Euch wirklich gut aneinander gewöhnt. Ihr werdet ihn reiten können, sobald ich Euren Sattel und das Zaumzeug fertiggestellt habe. Genau wie Ihr müssen die Materialien speziell behandelt werden, um den Giften zu widerstehen, die der Raptor erzeugt.\n\nAlles, was Ihr tun müsst, ist mir etwas unverwüstliches Leder, Runenstoff und Geld für den Rest des Materials zu bringen. Dann werde ich den Sattel im Handumdrehen fertiggestellt haben.", sourceObjective = "Bringt Mor'vek im südöstlichen Teil der Marschen im Krater von Un'Goro 20 unverwüstliche Leder, 20 Runenstoff und 80 Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13914] = { id = 13914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sengende Rocfedern", description = "Das Junge sieht Euch für einen Moment an, ein wenig, also ob es sich fragt, ob Ihr verstehen werdet. Es kratzt ein Bild von einem Paar Federn in die Erde, bevor es mit einer Klaue auf die Lederbänder um seine Ellbogen und Knie zeigt.\n\nEs sieht nicht hungrig aus, aber wofür könnten die Federn gut sein?\n\nEs will sie wohl als Schmuck haben, wie Ihr ihn an den anderen Raptoren gesehen habt. Die größten Federn findet man bei den sengenden Rocs, welche die großen Tierknochen in der westlichen Tanariswüste umschwärmen, nordöstlich des Disteltals.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr ihm 5 Federn von sengenden Rocs bringt.", progress = "Euer Gifthautjunges sieht Euch erwartungsvoll an.", completion = "Das Gifthautjunge nimmt die Federn an sich und begutachtet sie, während es einige an seine Armbänder hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[13915] = { id = 13915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sooooo hungrig", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen sind grob, aber Ihr könnt die Umrisse von Dimetrodonten, Stegodonten und Pterrordaktylen ausmachen. Als der Raptor die Zeichnung vervollständigt hat, sieht er wieder zu Euch auf, fletscht seine Zähne und schnappt ein paar Mal mit dem Maul.\n\nAnscheinend hat Euer Gifthautjunges Hunger auf frisches Fleisch von diesen Tieren. Findet und tötet Dimetrodonten, Stegodonten oder Pterrordaktylen im Krater von Un'Goro und füttert Euer hungriges Junges mit ihrem Fleisch.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 15 frische Dinosaurierfleischstücke an ihn verfüttert.", progress = "Das Gifthautjunge leckt sich das Maul und legt den Kopf schräg.", completion = "Das Gifthautjunge scheint mit der gewaltigen Mahlzeit, die Ihr ihm serviert habt, durchaus zufrieden. Es lässt sich allerdings schwer sagen, wann es wieder hungrig sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13916] = { id = 13916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pochiert, gerührt oder roh?", description = "Der Magen des Gifthautjungen knurrt, als es mit seinen Ärmchen wedelt, um Eure Aufmerksamkeit zu bekommen. Es beginnt, die Umrisse von Silithiden in die Erde zu kratzen, darunter einige Ovale. Es sieht Euch hoffnugsvoll an und deutet auf die Kreise.\n\nSie können nur Silithideneier darstellen. Der giftige Unterschlupf im westlichen Tanaris, nahe der Grenze zum Krater von Un'goro, wäre sicherlich ein guter Ort, um die Eier zu finden, die Euer kleines Junges haben möchte.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 12 Silithideneier an ihn verfüttert.", completion = "Euer Junges leckt sich das Mäulchen, nachdem es die Riesenportion Silithideneier verschlungen hat. Für einen Moment glaubt Ihr, es sieht ein wenig enttäuscht aus, dass die Fütterungszeit schon vorbei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13917] = { id = 13917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorishigelee", description = "Das Gifthautjunge sieht Euch erwartungsvoll an und beginnt dann, ein Piktogramm in den Boden zu kratzen.\n\nDie Zeichnungen des Jungen scheinen verschiedene Arten großer Insekten darzustellen, vielleicht die Gorishisilithiden. Das Junge beendet seine Zeichnung, zeigt mit einem kurzen Arm darauf, schnappt mit dem Kiefer und leckt sich das Mäulchen.\n\nEs möchte wohl, dass Ihr zur wuchernden Narbe, im Zentrum des südlichen Kraters von Un'goro geht und Silithidenfleisch sammelt. Wenn Ihr das Fleisch habt, gebt es Eurem hungrigen Jungen zu fressen.", sourceObjective = "Euer Gifthautjunges möchte, das Ihr 10 Stück Silithidenfleisch an ihn verfüttert.", completion = "Das Gifthautjunge grinst Euch mit spitzen Zähnen zufrieden an und rollt sich dann zum Schlafen zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13926] = { id = 13926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines Waisenkind Roo von den Orakeln", description = "Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, {name}. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.\n\nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.\n\nBitte, {name}, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.", sourceObjective = "Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Orakelwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13927] = { id = 13927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleines Waisenkind Kekek von den Wolvar", description = "Die Waisen haben sich auf eine Gelegenheit gefreut, einen Freund wie Euch zu treffen, {name}. Es ist wunderbar, dass Ihr zugestimmt habt, Euch um einen von ihnen zu kümmern.\n\nNehmt diese Pfeife. Mit Ihr könnt Ihr das Waisenkind rufen, das Ihr unter Eure Fittiche nehmen möchtet. Sie wird nur für begrenzte Zeit funktionieren - de facto nicht länger als die Kinderwoche selbst dauert.\n\nBitte, {name}, ruft Euer Waisenkind. Es wird sich freuen, Euch zu treffen und mit Euch zusammen die Sehenswürdigkeiten von Nordend anzusehen.", sourceObjective = "Sprecht mit Waisenmatrone Aria und benutzt dann die Pfeife des Wolvarwaisenkindes, um das Waisenkind zu rufen, für das Ihr während der Kinderwoche sorgen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13929] = { id = 13929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der grööößte Baum überhaupt!", description = "Bevor der große Krieg passiert war und wir das Dorf verlassen haben, wir erinnern uns dran, wie Soo-say uns vom größten von allen Bäumen erzählt hat!\n\nSoo-say es nennen Grauschlund oder so. Soo-say uns erzählen, es ist in der Mitte von den Kritzlihügeln. Nein, warte. Das nicht was Soo-say gesagt hat. Soo-say sagt Grizzlyhügel. Jetzt wir uns erinnern! Großer Baum und in der Mitte von Grizzlyhügeln. Kann gar nicht übersehen!\n\nDu uns bringen dahin, oki? Wir uns anschauen den großen Baum von innen? Soo-say sagen, große Bärenleute leben auch im Baum. Vielleicht wir sie auch sehen.", sourceObjective = "Besucht mit Eurem Waisenkind Roo den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13930] = { id = 13930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimat der Bärenleute", description = "Hochschamane Rakjak uns immer Geschichten von mächtigen Kriegern erzählt, auch von weit weit weg. Manchmal er hat erzählt über riesige Bärenleute, wo einen großen Krieg um eine große Baumstadt kämpfen.\n\nVielleicht du bringt Kekek dort hin, Baum anschauen, Kampf anschauen! Hochschamane Rakjak erzählt Kekek, die große Baumstadt Grauschlund steht in der Mitte von den Grizzlyhügeln.\n\nKekek hat nie eine Stadt gesehen, bevor er kennengelernt hat die Waisendame, aber die Stadt hier hat keine Krieger, nur Männer in lila Kleidern. Kekek will richtige Krieger sehen, die um eine richtige Stadt kämpfen.", sourceObjective = "Besucht mit Eurem Waisenkind Kekek den Grauschlund. Falls er nicht anwesend ist, wenn Ihr den großen Baum betretet, solltet Ihr nach ihm rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13931] = { id = 13931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Jahr, ein neues Souvernir", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Gutscheine einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNaja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13932] = { id = 13932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Jahr, ein neues Souvernir", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Ooch, es ist nur ein Gutschein für einen Braufestkrug... vielleicht gebt Ihr Euch ja auch nur so unnahbar. So, hier habt Ihr den diesjährigen Krug.\n\nIch nehme an, dass ich Euch noch öfter hier sehen werde. Denn wenn Ihr Eure Gutscheine einlösen möchtet, dann bin ich Euer Mädel hier...\n\noder vielleicht seins...\n\nooohhh.... oder seins...", sourceObjectiveStatus = "unverified-source-field" }
quests[13933] = { id = 13933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bronzedrachenschrein", description = "Manchmal Hochorakel Soo-say erzählt Geschichten über Schreine für Drachendinger, nicht wie großer Regenstein, aber anders. Soo-say sagt uns, vielleicht wir uns dort selbst sehen, aber nicht wie in Glitzer-Glitzer. Soo-say meint, wir uns dort sehen, wie wenn in vielen Jahren später.\n\nBringst du uns dorthin? Wir uns erinnern, Schrein für Bronzedrachendinger ist in einem Ort, der Drachenöde heißt. Soo-say sagt, großer Regenstein zeigt ihm Schrein im Nordosten vom Wyrmruhtempel, oder nordwestlich von einem Ort, den die Trockenhäute Feste Wintergarde nennen. Wir gehen?", sourceObjective = "Besucht mit Eurem Waisenkind Roo den Bronzedrachenschrein. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13934] = { id = 13934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bronzedrachenschrein", description = "Als Kekek noch ein Welpe war, er hat die Ältesten oft von einem Schrein reden hören, weit weg. Manchmal sie sagen, dass die Bronzedrachendinger dort alles über die Zukunft wissen.\n\nKekek dir sagt, er wird großer Krieger sein, wir jetzt gehen nachsehen. Bronzedrachendingschrein ist irgendwo in Drachenöde, nordöstlich von Drachendingtempel, was Wyrmruh genannt wird und nordwestlich von Menschenstadt, was Wintergarde heißt.\n\nWir dort hingehen und Zukunft anschauen. Beweisen, dass Waisendame unrecht hat. Kekek sein Krieger, kein Lümmel.", sourceObjective = "Besucht mit Eurem Waisenkind Kekek den Bronzedrachenschrein. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13937] = { id = 13937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei den Wunderwerken", description = "Haben wir Zeit für noch einen Halt? Wir haben gehört, dass Dalaran hat einen Spielzeugladen, aber wir dürfen nie hingehen. Waisendame sagt, zu viele Waisen würden sich in Laden drängen. Vielleicht können wir gehen, nur wir?\n\nKönnen wir ein kleines Papierzeppelin haben? Wir denken, sie haben sowas bei Wunderwerke in Dalaran. Wir wollten schon immer mit sowas spielen. Vielleicht du uns eins zuwerfen?", sourceObjective = "Kauft einen kleinen Papierzeppelin bei den Wunderwerken und werft ihn Eurem Waisenkind, Roo, zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[13938] = { id = 13938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei den Wunderwerken", description = "Du bringen Kekek zu noch einen Ort? Waisenfrau sagt, dass Dalaran Spielzeugladen hat, der Wunderwerke heißt, aber Kekek den noch nie gesehen. Sie sagt, dass, wenn ein Waisenkind hingeht, sie jeden hinbringen muss. Vielleicht du bringen Kekek dorthin?\n\nKekek hat andere Kinder gesehen, die mit kleinen Papierzeppelin spielen? Kekek gehört, dass die von Wunderwerken kommen. Vielleicht du einen besorgen und ihn gemeinsam mit Kekek herumwerfen?", sourceObjective = "Kauft einen kleinen Papierzeppelin bei den Wunderwerken und werft ihn Eurem Waisenkind, Kekek, zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[13950] = { id = 13950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielgefährten!", description = "Im Waisenhaus kann es schon sehr einsam werden, weißt du? Manchmal wollen wir mal rauskommen, neue Freunde finden.\n\nVielleicht kannst du uns irgendwohin mitnehmen, wo andere Junge sind? Wir haben von einem Ort gehört, der Zuflucht der Winterflossen genannt wird, in der großen boreanischen Tundra. Wir glauben, dass es ganz weit drüben sein, im Nordwesten, in der Nähe der Kante der Kaltarrainsel.\n\nDie Waisendame sagen, dass jemand Tapferes dort ein paar Junge gerettet hat. Wir glauben, sie sind auch einsam. Wir glauben, sie brauchen Freunde. Bringst du uns hin?", sourceObjective = "Nehmt Euer Waisenkind, Roo, und besucht die Zuflucht der Winterflossen. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13951] = { id = 13951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielgefährten!", description = "Kekek ist der Meinung, es gibt nicht genügend andere Welpen, die auch bei der Waisendame leben. Vielleicht gehen wir und besuchen ein paar?\n\nKekek kennt einen Stamm, der in der Drachenöde lebt, an einem Ort, der Schneewehenlichtung heißt. Du kennst? Schneewehenlichtung ist im Norden von einer Walrossstadt, die heißt Hafen Mo'aki, und im Süden von Rubindrachenschrein.\n\n<Kekek knurrt bei der Erwähnung der Tuskarr.>\n\nDu bringst Kekek da hin, zu ein paar von den Dörfern dort. Vielleicht treffen wir neue Wolvar und zeigen ihnen, wie stark die Wildherzen sind!", sourceObjective = "Nehmt Euer Waisenkind, Kekek, und besucht die Schneewehenlichtung. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13952] = { id = 13952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Menschengeist auf dem Friedhof von Sturmwind.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13954] = { id = 13954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drachenkönigin", description = "In einer von Hochorakels Soo-says Geschichten es heißt, die Großen haben die Drachen gemacht und auch die Königin für die Drachen. Wir wollen sie sehen! Würdest du uns mitnehmen zur Spitze des Wyrmruhtempels? Wir erinnern uns, dass Soo-say uns erzählt hat, dass das Tempeldings in der Mitte der Drachenöde war.\n\nWir wollen wirklich so gerne die Drachenkönigin treffen. Sie muss so groß und schön sein. Vielleicht hilft sie uns, neue Eltern zu finden.\n\nDu uns nehmen mit?", sourceObjective = "Nehmt Euer Waisenkind, Roo, und besucht Alexstrasza die Lebensbinderin auf der Spitze des Wyrmruhtempels. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13955] = { id = 13955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drachenkönigin", description = "Kekek hat Drachen immer gemocht. Wollte immer einer sein, aber Waisendame hat nein gesagt. Aber sie hat gesagt, dass vielleicht du Kekek zur Drachenkönigin bringen kannst.\n\nKekek glaubt, Waisendame hat einmal eine gute Idee. Du bringst Kekek zum Wyrmruhtempel in der Drachenöde? Fliegen ganz hoch bis zur Spitze, um Drachenkönigin zu sehen. Sie muss riesig groß sein, damit sie Königin von allen Drachen ist. Kekek kann es gar nicht erwarten, sie zu sehen!", sourceObjective = "Nehmt Euer Waisenkind, Kekek, und besucht Alexstrasza die Lebensbinderin auf der Spitze des Wyrmruhtempels. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13956] = { id = 13956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Großen treffen", description = "Hochorakel Soo-say erzählt uns immer, wie die Großen Schreine gebaut haben und wir ihnen Glitzer-Glitzer geben, aber er hat Große nie gesehen. Niemand hat Große gesehen, vielleicht weißt du, wo wir einen finden?\n\nSoo-say erzählt uns, die Großen haben ein Tor gebaut und es in die Mitte vom Süden von Sholazar gestellt. Soo-say sagt nicht, wo es hinführt, aber vielleicht er führt zu einem Großen! Bringt uns durch das Tor, damit wir es rausfinden können, {name}.", sourceObjective = "Nehmt Euer Waisenkind, Roo, und besucht den Etymidian auf der Terrasse des Formers. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13957] = { id = 13957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mächtige Hemet Nesingwary", description = "Weißt du, wen Kekek immer schon mal treffen wollte? Hemet Nesingwary.\n\nVielleicht kannst du Kekek mitnehmen, um ihn zu sehen? Der Älteste Harkek hat uns alles von ihm erzählt. Er kommt nach Sholazar, um die größten Tiere weit und breit zu jagen! Sogar Älteste der Wildherzen respektieren Hemet Nesingwary als großen Jäger.\n\nDer Älteste Harkek hat Kekek erzählt, dass Nesingwarys Basislager in der Mitte der Westseite von Sholazar, beim Fluss, der Meeresklammstrom genannt wird. Können wir ihn besuchen und lernen, wie man wie Hemet jagt?", sourceObjective = "Nehmt Euer Waisenkind, Kekek, und besucht Hemet Nesingwary in Nesingwarys Basislager. Falls er nicht anwesend ist, wenn Ihr eintrefft, solltet Ihr nach ihm rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13959] = { id = 13959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", sourceObjective = "Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Orakelwaisenkindes überreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13960] = { id = 13960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", sourceObjective = "Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Wolvarwaisenkindes überreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13966] = { id = 13966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen des Geschenks steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13986] = { id = 13986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verletzter Kollege", description = "Es war ein harter Kampf hier oben, {class}, wie Ihr sicher wisst. Wir harren aus, doch ist nicht jeder unversehrt geblieben.\n\nEine der Kriegerinnen unserer Gruppe, Aponi Lichtmähne, leidet an einer infizierten Wunde an ihrem Arm. Sie wurde zur Erholung nach Donnerfels zurückgebracht. Es scheint jedoch, als hätte sie in der ganzen Aufregung ihren Schild hier an der Front vergessen - könntet Ihr es ihr bringen, zusammen mit unseren Genesungswünschen? Uns fehlt ihr Lächeln hier sehr.\n\nIhr könnt sie auf der Anhöhe der Ältesten finden.", sourceObjective = "Bringt Aponi Lichtmähne auf der Anhöhe der Ältesten in Donnerfels den ramponierten Stammesschild.", progress = "Oh! Hallo. Ich glaube nicht, dass wir uns schon kennengelernt haben. Gibt es etwas, was ich für Euch tun kann?", completion = "Oh, mein Schild! Ich werde ihn in naher Zukunft wohl nicht brauchen, aber ich danke Euch. Ich verabscheue es, hier nutzlos herumzusitzen, wenn ich an der Front helfen könnte, doch würde es niemandem helfen, wenn ich mich in den Kampf werfe, solange mein Arm in diesem Zustand ist.\n\nGebt gut auf Euch acht da draußen, in Ordnung?", sourceObjectiveStatus = "unverified-source-field" }
quests[13997] = { id = 13997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You're Reading This While I'm In Combat..." }
quests[14016] = { id = 14016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch des Schwarzen Ritters", description = "Ich wollte die Überreste des Schwarzen Ritters nach Eurem Sieg vom Turnierplatz entfernen lassen, aber Argentumbeichtpatin Blondlocke bestand darauf, dass er ein ordentliches Begräbnis erhält. Seither hält sich eine düstere Gegenwart hartnäckig auf dem Friedhof, und niemand wagt sich mehr dorthin, um die Gefallenen zu ehren.\n\nWürdet Ihr dem Friedhof gleich außerhalb des Turnierplatzes im Osten einen Besuch abstatten und sehen, ob Ihr herausfinden könnt, was dort vor sich geht?", sourceObjective = "Kreuzfahrerin Rhydalla auf dem Argentumturnierplatz möchte, dass Ihr das Grab des Schwarzen Ritters untersucht.", completion = "<Kreuzfahrerin Rhydalla runzelt die Stirn.>\n\nGlaubt Ihr, sie haben das geplant? Spielt vermutlich keine Rolle, doch es gefällt mir nicht, dass wir ihnen womöglich genau in die Hände gespielt haben. Was immer auch vor sich geht, wir müssen es vereiteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[14017] = { id = 14017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal des Schwarzen Ritters", description = "Ihr sagt, dass Kultisten die Leiche entfernt haben? Mir fällt da nur ein Ort ein, zu dem sie sie gebracht haben können: Todessprechers Wacht, das Lager auf der Anhöhe westlich des Turnierplatzes.\n\nWas auch immer die Kultisten vorhaben, man muss sie aufhalten. Die Gerüchte, die ich gehört habe, können also nur wahr sein. Der berüchtigte Doktor Kohler muss unter den Kultisten sein und seine Kunst ausüben. Sucht nach einer Anhöhe oder einem Altar, von dem aus man Sicht auf das Kultistenlager hat. Tötet den Doktor und sucht nach Beweisen über seine Machenschaften. Bremst ihn bei seiner Arbeit, egal wie.", sourceObjective = "Geht nach Todessprechers Wacht, bringt Doktor Kohlers Befehle in Euren Besitz und kehrt dann zu Kreuzfahrerin Rhydalla auf dem Argentumturnierplatz zurück.", progress = "Habt Ihr herausgefunden, was sie mit den Überresten des Schwarzen Ritters machen?", completion = "Der Doktor wird keine Zeit haben, sein Werk zu vollenden, aber sein Plan wurde schon ins Rollen gebracht. Laut Euren Berichten haben die Diener des Lichkönigs den Schwarzen Ritter wiederbelebt und mit neuer Kraft erfüllt - niemand kann sagen, was sein Meister im Schilde führt. Diese Verschwörung aufzudecken war gute Arbeit. Ich werde dem Hochmeister Adelard von Euren Funden berichten und gemeinsam werden wir die Teilnehmer des Turniers davor warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14022] = { id = 14022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilgerfreuden", description = "Möchtet Ihr nicht vielleicht das Pilgerfreudenfest mit uns feiern, {name}? Dies ist eine Zeit des Besinnens auf Eure Reisen und Euer Glück, eine Zeit des Teilens - von gutem Essen und unterhaltsamen Geschichten!\n\nIhr könnt an den wundervollen Pilgerfreudenfeierlichkeiten in der Nähe der größeren Städte teilhaben, indem Ihr an einer der Festtafeln Platz nehmt und das vorhandene Essen verteilt.\n\nWenn Ihr lernen möchtet, wie man die traditionellen Pilgerfreudenspeisen zubereitet, sucht Gregory Tabor auf. Ihr findet ihn vor den Toren von Sturmwind.", sourceObjective = "Sprecht mit Gregory Tabor außerhalb der Tore Sturmwinds.", completion = "Wenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, kann ich Euch helfen. Falls Ihr noch keine Kochkenntnisse besitzt, braucht ihr nur ein wenig zu üben und im Nu seid Ihr ein richtiger Koch!", sourceObjectiveStatus = "unverified-source-field" }
quests[14023] = { id = 14023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrotfüllung", description = "Unsere Gewürzbrotfüllung ist das Prunkstück der Pilgerfreudentafel. Das Rezept war schon immer besonders beliebt in Sturmwind und hat nun seinen rechtmäßigen Platz im Pilgerfreudenfest-Kochbuch eingenommen.\n\nWenn Ihr in der Kochkunst bereits bewandert seid, könnt Ihr Euer Exemplar des Kochbuchs und alle benötigten Zutaten für ein Festmahl vom Händler des Pilgerfreudenfests erstehen. Und seid Ihr es nicht, so ist jetzt die beste Gelegenheit, dies zu ändern!\n\nHabt Ihr die Gewürzbrotfüllung zubereitet, bringt sie zu Jasper Moore, in der Nähe der Festtafel.", sourceObjective = "Bereitet 5 Portionen Gewürzbrotfüllung zu und bringt sie zu Jasper Moore an die Festtafel außerhalb der Tore Sturmwinds.", progress = "Wir können immer etwas von der köstlichen Gewürzbrotfüllung gebrauchen, sie ist ausgesprochen beliebt.", completion = "Ausgezeichnet. Genau was wir brauchen! Es ist harte Arbeit, dafür zu sorgen, dass die Tische niemals leer werden, doch es lohnt sich!", sourceObjectiveStatus = "unverified-source-field" }
quests[14024] = { id = 14024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürbiskuchen", description = "Eure Gewürzbrotfüllung riecht ausgesprochen verlockend, doch keine Pilgerfreudentafel ist ohne einen prächtigen Kürbiskuchen komplett. Dies ist ein weiteres sehr beliebtes Gericht hier in Sturmwind, denn Kürbiskuchen wird aus den reifen Elwynnkürbissen zubereitet, die nur hier gedeihen.\n\nSolltet Ihr nicht wissen, wie man ihn zubereitet, könnt Ihr das Rezept in Eurem Pilgerfreundenfest-Kochbuch finden.\n\nWürde es Euch etwas ausmachen, einige Kuchen zuzubereiten und sie Edward Winslow zu bringen, außerhalb von Eisenschmiede? Sein Vorrat ist sicherlich schon knapp geworden.", sourceObjective = "Bereitet 5 Kürbiskuchen zu und bringt sie Edward Winslow an die Festtafel außerhalb von Eisenschmiede.", progress = "Mehr Kürbiskuchen? Genau rechtzeitig.", completion = "Der Kürbiskuchen ist hier oben ausgesprochen beliebt. Ich habe noch nie zuvor gesehen, dass Zwerge über ein Gemüsegericht so aus dem Häuschen geraten!", sourceObjectiveStatus = "unverified-source-field" }
quests[14028] = { id = 14028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosbeerenchutney", description = "Wenn Ihr bislang noch nie Moosbeerenchutney versucht habt, dann entgeht Euch etwas! Es wird aus den frischesten, schmackhaftesten Moosbeeren des ganzen Sumpflands zubereitet. Ersteht einfach welche vom nächsten Händler des Pilgerfreudenfests, wenn Ihr Euch an der Zubereitung versuchen wollt.\n\nDas Rezept findet Ihr in Eurem Pilgerfreudenfest-Kochbuch.\n\nWenn Ihr nicht in Eile seid, würdet Ihr vielleicht etwas Chutney zubereiten und zu Jasper Moore bringen, außerhalb Sturmwinds? Ich habe ihm versprochen, es gegen den Kuchen einzutauschen, den Ihr mir gebracht habt.", sourceObjective = "Bereitet 5 Portionen Moosbeerenchutney zu und bringt sie zu Jasper Moore an die Festtafel außerhalb Sturmwinds.", progress = "Rieche ich da etwa Moosbeerenchutney?", completion = "Endlich, das versprochene Moosbeerenchutney! Ihr glaubt ja nicht, wie schnell die Feiernden das immer verputzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14030] = { id = 14030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassus darbt", description = "Vielen Dank für das Moosbeerenchutney. Es gibt so viel zuzubereiten, ich kann kaum noch einen klaren Gedanken fassen! Und zu all dem kommt nun noch, dass Isaac Allerton in Darnassus mittlerweile praktisch alle Zutaten ausgegangen sind! Ich kann wohl kaum erwarten, dass Ihr so gut wäret, einzuspringen und etwas mehr Gewürzbrotfüllung und Kürbiskuchen zuzubereiten, oder? Der Händler sollte alle Zutaten parat haben, die Ihr benötigen würdet.\n\nIhr könnt ihn in der Nähe der Festtafel finden, auf der Wiese hinter der Terrasse der Krieger in Darnassus.", sourceObjective = "Bringt 5 Portionen Gewürzbrotfüllung und 5 Kürbiskuchen zu Isaac Allerton in der Nähe des Eingangs nach Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[14032] = { id = 14032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung im Koboldlager", description = "Eure erste Aufgabe ist eine Säuberung, {name}. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.", sourceObjective = "Tötet 8 von dem Koboldgezücht und kehrt dann zu Marschall McBride zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[14033] = { id = 14033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kandierte Süßkartoffeln", description = "Solange Ihr hier seid, solltet Ihr Euch einen Vorrat an Süßkartoffeln von Teldrassil zulegen. Aus ihnen werden die köstlichsten kandierten Süßkartoffeln zubereitet, die Ihr je schmecken werdet!\n\nWenn Ihr mir nicht glaubt, sucht das Rezept aus Eurem Pilgerfreudenfest-Kochbuch heraus und probiert es mal! Und solltet Ihr welche übrig haben, könntet Ihr sie mit Gregory Tabor in der Nähe der Festtafel außerhalb Sturmwinds teilen. Er liebt diese Kartöffelchen! Aber wenn man ihm so zuhört, gewinnt man den Eindruck, er liebt alles, was man essen kann.", sourceObjective = "Bereitet 5 Portionen kandierte Süßkartoffeln zu und bringt sie zu Gregory Tabor außerhalb der Tore Sturmwinds.", sourceObjectiveStatus = "unverified-source-field" }
quests[14035] = { id = 14035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langsam gerösteter Truthahn", description = "Jedes Pilgerfreudenfestmahl benötigt einen Mittelpunkt der Tafel, und damit meine ich kein dekoratives Füllhorn. Nein, die wahre Krönung der Tafel ist ein schmackhafter gerösteter Truthahn.\n\nIhr findet ein fabelhaftes Rezept dafür in Eurem Pilgerfreudenfest-Kochbuch. Warum erlegt Ihr nicht ein paar wilde Truthähne und bereitet sie selbst zu? Diese Tierchen sind überall im Wald von Elwynn unterwegs, Ihr solltet sie leicht aufspüren können.\n\nKönnt Ihr sie zu Isaac Allerton an die Tore von Darnassus bringen, sobald sie fertig zubereitet sind?", sourceObjective = "Bereitet 5 langsam geröstete Truthähne zu und bringt sie zu Isaac Allerton, in der Nähe der Tore von Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[14036] = { id = 14036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilgerfreuden", description = "Seid Ihr hier, um mit uns das Pilgerfreudenfest zu feiern? Dies war einst eine Zeit der Einkehr und des Gedenkens an getane Reisen und das Glück, ein gutes Mahl mit Freunden teilen zu können. Noch heute feiern viele das Fest.\n\nIhr könnt an Pilgerfreudenfeierlichkeiten in der Nähe größerer Städte teilnehmen, indem Ihr an einer der Festtafeln Platz nehmt und das dort vorhandene Essen verteilt.\n\nWenn Ihr an der Zubereitung traditioneller Pilgerfreudengerichte interessiert seid, wendet Euch an Miles Standish im Innenhof über Unterstadt.", sourceObjective = "Sprecht mit Miles Standish im Innenhof über Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14037] = { id = 14037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzbrotfüllung", description = "Unsere Gewürzbrotfüllung ist das A und O der Pilgerfreudentafel. Das Rezept stammt aus besseren Tagen in Lordaeron und hat nun seinen Platz unter den traditionellen Gerichten gefunden.\n\nSeid Ihr bereits in der Kochkunst bewandert, stattet dem Händler des Pilgerfreudenfests einen Besuch ab und Ihr erhaltet Euer eigenes Exemplar des Pilgerfreundenfest-Kochbuchs und alle hiesigen Zutaten, die Ihr benötigt, um ein Festmahl zuzubereiten. Seid Ihr noch unerfahren in der Kunst des Kochens, so ist dies die beste Gelegenheit für Euch, zu beginnen!\n\nSobald Ihr die Füllung zubereitet habt, übergebt sie William Mullins in der Nähe der Festtafel.", sourceObjective = "Bereitet 5 Portionen der Gewürzbrotfüllung zu und bringt sie dann zu William Mullins an die Festtafel im Innenhof über Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14040] = { id = 14040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürbiskuchen", description = "Eure Gewürzbrotfüllung ist einfach wunderbar, aber uns fehlt noch der ein oder andere Kürbiskuchen zum Glück. Ein weiteres traditionelles Gericht der Region, denn hierzu werden reife Tirisfalkürbisse verwendet, die nirgends sonst gedeihen. \n\nFalls Ihr nicht wisst, wie man sie zubereitet, findet Ihr das Rezept in Eurem Pilgerfreudenfest-Kochbuch.\n\nMacht es Euch etwas aus, uns ein paar zuzubereiten und sie Francis Eaton außerhalb von Orgrimmar zu bringen? Ich bin sicher, es sind nicht mehr viele übrig.", sourceObjective = "Bereitet 5 Stücke Kürbiskuchen zu und bringt sie zu Francis Eaton an die Festtafel außerhalb von Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[14041] = { id = 14041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosbeerenchutney", description = "Habt Ihr einmal das Moosbeerenchutney versucht? Es wird aus frischen, schmackhaften säuerlichen Moosbeeren vom Südstrom zubereitet. Besorgt Euch einfach welche vom Händler des Pilgerfreudenfests, wenn Ihr Euch mal am Rezept versuchen wollt.\n\nIhr findet es in Eurem Pilgerfreudenfest-Kochbuch.\n\nWenn Ihr nicht zu viel zu tun habt, könntet Ihr vielleicht etwas Chutney zubereiten und es zu Dokin Grasland am Fuße des Aufzugs bringen, westlich von Donnerfels?", sourceObjective = "Bereitet 5 Portionen Moosbeerenchutney zu und bringt sie zu Dokin Grasland am Fuße des Aufzugs westlich von Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[14043] = { id = 14043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kandierte Süßkartoffeln", description = "Da Ihr schon mal hier seid, solltet Ihr gleich Euren Vorrat an Süßkartoffeln aus Mulgore aufstocken. Sie werden für die Zubereitung kandierter Süßkartoffeln verwendet, mein absoluter Favorit auf der Festtafel.\n\nWenn Ihr meinem Urteil nicht traut, sucht Euch das Rezept heraus und probiert es einmal! Solltet Ihr unterwegs nach Orgrimmar sein, könnt Ihr sie gleich zu Francis Eaton in der Nähe der Festtafel direkt außerhalb der Stadt bringen. Ich bemühe mich, ihn ausreichend zu versorgen, aber dort geht immer alles so schnell weg!", sourceObjective = "Bereitet 5 Portionen kandierte Süßkartoffeln zu und bringt sie zu Francis Eaton außerhalb der Tore Orgrimmars.", sourceObjectiveStatus = "unverified-source-field" }
quests[14044] = { id = 14044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstadt ist unterversorgt", description = "Vielen Dank für die kandierten Süßkartoffeln. Es gibt soviel zu kochen, ich komme kaum hinterher! Und jetzt schickt mir Miles auch noch eine Nachricht, dass ihm Gewürzbrotfüllung und Moosbeerenchutney ausgehen! Ihr hättet nicht zufällig Zeit, mir damit noch etwas unter die Arme zu greifen und ein wenig mehr von beidem zu kochen? Der Händler sollte alle nötigen Zutaten vorrätig haben.\n\nIhr könnt Miles Standish in der Nähe der Festtafel finden, im Innenhof in den Ruinen über Unterstadt.", sourceObjective = "Bringt 5 Portionen Gewürzbrotfüllung und 5 Portionen Moosbeerenchutney zu Miles Standish in der Nähe des Eingangs von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14047] = { id = 14047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langsam gerösteter Truthahn", description = "Zu jedem Pilgerfreudenfestmahl gehört ein kulinarischer Höhepunkt - für uns ist das ein langsam gerösteter Truthahn. Es gibt nichts besseres, um ein reichhaltiges Mahl angemessen zu krönen!\n\nIhr findet ein gutes Rezept dafür in Eurem Pilgerfreudenfest-Kochbuch. Warum jagt Ihr nicht ein paar Truthähne und bereitet sie dann zu? Sie sind überall in Tirisfal zu finden.\n\nWenn sie fertig sind, könntet Ihr sie dann zu Francis Eaton außerhalb von Orgrimmar bringen?", sourceObjective = "Bereitet 5 langsam geröstete Truthähne zu und bringt sie zu Francis Eaton, in der Nähe der Tore von Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[14048] = { id = 14048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich krieg einfach nicht genug ... Truthahn", description = "Ich hab schon vor den Feiertagen angefangen zu kochen und seitdem nicht mehr aufgehört! Und es ist trotzdem nie genug - könnte ich Euch vielleicht überreden, mir zur Hand zu gehen?\n\nTruthahn bekommt man hier schwer, wenn Ihr mir also ein paar langsam geröstete Truthähne bringen könntet, wäre das eine enorme Hilfe. Möchtet Ihr ihn selbst zubereiten, könnt Ihr die Truthähne überall in Tirisfal selbst erjagen. Alle weiteren Zutaten erhaltet Ihr bei jedem Händler des Pilgerfreudenfests.", sourceObjective = "Bringt 20 langsam geröstete Truthähne zu Caitrin Eisenkessel außerhalb von Eisenschmiede.", progress = "Habt Ihr ein paar Truthähne aufgespürt?", completion = "Genau das Richtige, vielen Dank, {name}. Ihr habt es genau getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14051] = { id = 14051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Füllung ist alles!", description = "Dafür zu sorgen, dass die Festtafeln gefüllt bleiben, ist kein Kinderspiel! Ich muss das Moosbeerenchutney zubereiten, die Süßkartoffeln im Auge behalten und gleichzeitig auch noch dafür sorgen, dass der Kürbiskuchen nicht anbrennt.\n\nIch glaube, ich habe alles soweit im Griff. Moment, ich habe doch irgendwas vergessen ... Oh nein, die Füllung! Jetzt bleibt mir keine Zeit mehr dafür, bevor ich nicht mit dem Rest fertig bin. Äh, vielleicht könntet Ihr mir da aushelfen? Es sollte nicht allzu lang dauern, etwas Gewürzbrotfüllung zu kaufen oder selbst zuzubereiten, die Zutaten könnt Ihr direkt hier besorgen.", sourceObjective = "Bringt 20 Portionen Gewürzbrotfüllung zu Caitrin Eisenkessel nahe der Festtafel außerhalb von Eisenschmiede.", progress = "Wie sieht es mit der Füllung aus?", completion = "Ein Glück, Ihr habt es geschafft! Ohne Gewürzbrotfüllung wäre das ganze Festmahl ein einziger Reinfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[14053] = { id = 14053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon wieder kein Moosbeerenchutney mehr?", description = "Mein Mann Jasper wollte eigentlich noch mehr Moosbeerenchutney zubereiten, aber wie es scheint, hat er schon genug mit den kandierten Süßkartoffeln für all die Gäste zu tun. Würdet ihr vielleicht aushelfen? Wenn Ihr in der Kochkunst bewandert seid, braucht Ihr nur die säuerlichen Sumpfmoosbeeren, die Ihr beim Händler des Pilgerfreudenfests außerhalb von Eisenschmiede bekommen könnt.\n\nFalls Euch nicht nach Kochen ist, könnt Ihr auch jederzeit jemand anderen um die Zubereitung des Chutneys bitten.", sourceObjective = "Bringt 20 Portionen Moosbeerenchutney zu Ellen Moore an die Festtafel außerhalb Sturmwinds.", progress = "Konntet Ihr etwas Moosbeerenchutney auftreiben?", completion = "Danke. Das sieht wirklich köstlich aus, und Ihr seid ein ganzes Stück schneller als Jasper - aber verratet ihm nicht, dass ich das gesagt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[14054] = { id = 14054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuchen versuchen", description = "Isaac arbeitet hart, um den Feiernden die traditionellen Ursprünge des Pilgerfreudenfests und die Zubereitung aus all den geernteten Zutaten in dieser Jahreszeit näher zu bringen. Ich bemühe mich, die Festtafeln schön gefüllt zu halten, aber Isaacs Leibspeise geht langsam zur Neige - Kürbiskuchen!\n\nKönntet Ihr welchen für uns organisieren? Wenn Ihr ihn selbst zubereiten wollt, benötigt Ihr reife Elwynnkürbisse vom Händler des Pilgerfreudenfests außerhalb Sturmwinds.", sourceObjective = "Bringt 20 Kürbiskuchen zu Mary Allerton an die Festtafel vor den Toren von Darnassus.", completion = "Die sind wunderbar. Isaac wird begeistert sein, und nicht nur er!", sourceObjectiveStatus = "unverified-source-field" }
quests[14055] = { id = 14055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein in die Kartoffeln, raus aus den Kartoffeln", description = "Meine Frau Ellen hat mich damit beauftragt, für gedeckte Tafeln zu sorgen, doch sie ändert ständig ihre Meinung. Zuerst sollte ich Kürbiskuchen zubereiten, nun sind es plötzlich kandierte Süßkartoffeln.\n\nIch habe aber schon mit dem Kuchen angefangen! Vielleicht könntet Ihr mir ja mit den Süßkartoffeln aushelfen? Sie wird sicher angenehm überrascht sein, wenn wir alle ihre Wünsche erfüllen.\n\nSolltet Ihr die Süßkartoffeln selbst kandieren wollen, müsst Ihr sie beim Händler des Pilgerfreudenfests in Darnassus erstehen. Ich danke Euch, {name}.", sourceObjective = "Bringt 20 kandierte Süßkartoffeln zu Jasper Moore an die Festtafel außerhalb von Sturmwind.", progress = "Habt ihr die kandierten Süßkartoffeln dabei?", completion = "Die sind genau richtig! Vielen Dank für Eure Hilfe, {name}. Das Festmahl wird rechtzeitig fertig sein, und Ellen wird sich sicher freuen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14058] = { id = 14058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein in die Kartoffeln, raus aus den Kartoffeln", description = "Roberta Carter hat mich beauftragt, eines der Festtagsgerichte zuzubereiten. Kandierte Süßkartoffeln! Normalerweise würde ich mich darum reißen, aber ich habe der Gastgeberin versprochen, mit ihr auf die Tafeln zu achten.\n\nEs wäre eine große Hilfe, wenn Ihr stattdessen für mich einige kandierte Süßkartoffeln organisieren könntet! Roberta würde mir nie vergeben, wenn ich sie im Stich lasse. \n\nWenn Ihr die Süßkartoffeln selbst kandieren wollt, müsst Ihr zunächst welche vom Händler des Pilgerfreudenfests in Donnerfels erstehen. Ich danke Euch für Eure Hilfe, {name}!", sourceObjective = "Bringt 20 kandierte Süßkartoffeln zu William Mullins an die Festtafel oberhalb von Unterstadt.", progress = "Habt Ihr die kandierten Süßkartoffeln?", completion = "Vielen Dank, {name}. Ich kann der Gastgeberin helfen und brauche Roberta dennoch nicht zu enttäuschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14059] = { id = 14059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon wieder kein Moosbeerenchutney mehr?", description = "Ich wünschte, ich wüsste, warum das Moosbeerenchutney immer so schnell alle ist. Manchmal habe ich das Gefühl, sie verfüttern es heimlich an die Monstrositäten, wenn gerade keiner hinschaut. Würdet Ihr uns helfen, für Nachschub zu sorgen? Wenn Ihr in der Kochkunst bewandert seid, könnt Ihr die benötigten säuerlichen Moosbeeren vom Südstrom vom Händler des Pilgerfreudenfests außerhalb von Orgrimmar bekommen.\n\nSteht Euch nicht der Sinn nach Kochen, könnt Ihr auch jederzeit jemand anderen darum bitten.", sourceObjective = "Bringt 20 Portionen Moosbeerenchutney zu Roberta Carter an die Festtafel in den Innenhof oberhalb von Unterstadt.", progress = "Konntet Ihr etwas Moosbeerenchutney auftreiben?", completion = "Vielen Dank für Eure Hilfe, und gebt mir Bescheid, falls Ihr jemals hinter das Geheimnis des ständig verschwindenden Chutneys kommen solltet!", sourceObjectiveStatus = "unverified-source-field" }
quests[14060] = { id = 14060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuchen versuchen", description = "Dokin und Laha bemühen sich, den Feiernden die Hintergründe des Fests und die Zubereitung der traditionellen Gerichte aus all den frisch geernteten Zutaten nahe zu bringen. Ich versuche, die Tische mit so viel Essen wie nur möglich gefüllt zu halten, aber uns geht langsam der Kürbiskuchen aus.\n\nWürdet Ihr vielleicht welchen für uns besorgen? Wenn Ihr ihn selbst zubereiten wollt, benötigt Ihr dafür reife Tirisfalkürbisse, die Ihr beim Händler des Pilgerfreudenfests oberhalb von Unterstadt bekommen könnt.", sourceObjective = "Bringt 20 Kürbiskuchen zu Mahara Goldweizen nahe der Festtafel außerhalb von Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[14061] = { id = 14061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich krieg einfach nicht genug … Truthahn", description = "Ich hab schon vor den Feiertagen angefangen zu kochen und seitdem nicht mehr aufgehört! Und es ist trotzdem nie genug - könnte ich Euch vielleicht überreden, mir zur Hand zu gehen?\n\nTruthahn bekommt man hier schwer, wenn Ihr mir also ein paar langsam geröstete Truthähne bringen könntet, wäre das eine enorme Hilfe. Möchtet Ihr ihn selbst zubereiten, könnt Ihr die Truthähne überall in Tirisfal selbst erjagen. Alle weiteren Zutaten erhaltet Ihr bei jedem Händler des Pilgerfreudenfests.", sourceObjective = "Bringt 20 langsam geröstete Truthähne zu Ondani Mühlenrad außerhalb von Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[14062] = { id = 14062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Füllung ist alles!", description = "Dafür zu sorgen, dass die Festtafeln gefüllt bleiben, ist kein Kinderspiel! Ich muss das Moosbeerenchutney zubereiten, die Süßkartoffeln im Auge behalten und gleichzeitig auch noch dafür sorgen, dass der Kürbiskuchen nicht anbrennt.\n\nIch glaube, ich habe alles soweit im Griff. Moment, ich habe doch irgendwas vergessen ... Oh nein, die Füllung! Jetzt bleibt mir keine Zeit mehr dafür, bevor ich nicht mit dem Rest fertig bin. Äh, vielleicht könntet Ihr mir da aushelfen? Es sollte nicht allzu lang dauern, etwas Gewürzbrotfüllung zu kaufen oder selbst zuzubereiten, die Zutaten könnt Ihr direkt hier besorgen.", sourceObjective = "Bringt 20 Portionen Gewürzbrotfüllung zu Ondani Mühlenrad an die Festtafel außerhalb von Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[14064] = { id = 14064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teilen an der Festtafel", description = "Ihr habt nicht wirklich die Pilgerfreuden genossen, wenn Ihr Euch nicht ordentlich an einem der reich gedeckten Tische den Bauch vollgeschlagen habt.\n\nBitte, setzt Euch doch und speist, soviel Ihr nur könnt! Ihr könnt selbst von Stuhl zu Stuhl rücken, oder andere darum bitten, Euch einige der Speisen weiterzureichen.\n\nSobald Ihr genug von jedem Gericht verspeist habt, kommt Ihr zu der Erkenntnis: Teilen macht Freude!", sourceObjective = "Verspeist fünf Portionen jedes Gerichts an einem reich gedeckten Tisch, bis Ihr zu der Erkenntnis kommt: Teilen macht Freude.", completion = "Was für ein Festmahl, hm?\n\nEs freut mich, dass Ihr zusammen mit uns die Bedeutung des Pilgerfreudenfests zelebrieren konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14065] = { id = 14065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teilen an der Festtafel", description = "Ihr habt nicht wirklich die Pilgerfreuden genossen, wenn Ihr Euch nicht ordentlich an einem der reich gedeckten Tische den Bauch vollgeschlagen habt.\n\nBitte, setzt Euch doch und speist, soviel Ihr nur könnt! Ihr könnt selbst von Stuhl zu Stuhl rücken, oder andere darum bitten, Euch einige der Speisen weiterzureichen.\n\nSobald Ihr genug von jedem Gericht verspeist habt, kommt Ihr zu der Erkenntnis: Teilen macht Freude!", sourceObjective = "Verspeist fünf Portionen jedes Gerichts an einem reich gedeckten Tisch, bis Ihr zu der Erkenntnis kommt: Teilen macht Freude.", sourceObjectiveStatus = "unverified-source-field" }
quests[14074] = { id = 14074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legt mal ein Bein zu", description = "Der Argentumkreuzzug hatte ein schnelles Schiff mit einer Ladung Weitschreiterfleisch und weiteren Vorräten entsendet, die für uns hier am Turnierplatz vorgesehen waren, doch nie eingetroffen sind. Späher berichteten uns von einem Angriff der Kvaldir, räuberische Vrykul, die Angst und Schrecken auf den Meeren verbreiten.\n\nSie haben die Crew erschlagen und die Ladung auf eine Insel namens Hrothgars Landestelle gebracht. Wenn Ihr Richtung Norden blickt, könnt Ihr sie schemenhaft erkennen, verborgen im Nebel. Würdet Ihr uns helfen, das Diebesgut zurückzubeschaffen? Ohne diese Weitschreiterbeine werden wir bald hungern müssen.", sourceObjective = "Beschafft 10 gestohlene Weitschreiterbeine zurück und bringt sie zu Narasi Schneedämmerung auf dem Argentumturnierplatz.", progress = "Konntet Ihr die gestohlenen Vorräte wiederbeschaffen?", completion = "Sie sehen etwas mitgenommen aus, doch sie sind noch immer genießbar. Die Kreuzzügler werden glücklich sein, dass etwas von der Ladung gerettet werden konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[14076] = { id = 14076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühstück der Champions", description = "Nun, da das Kolosseum fertiggestellt ist, haben wir vom Argentumkreuzzug die Bitte erhalten, bei der Pflege der Kreaturen zu helfen, die als Gegner für die Champions dienen werden.\n\nDie riesigen Jormungar ernähren sich womöglich auf die seltsamste Art und Weise: Sie wachsen heran, indem sie die Eier ihrer eigenen Artgenossen fressen, und die besten Eier stammen von den Tiefenjormungar.\n\nNehmt diese Trommel und begebt Euch in die Fußmarschen im Zentrum der Sturmgipfel. Spielt sie anschließend in der Nähe der Schneehügel, die Ihr dort seht. Scheucht die Tiefenjormungar auf, tötet sie und sammelt ihre Eiersäcke ein.", sourceObjective = "Beschafft Euch 4 Eiersäcke eines Jormungars und bringt sie zu Savinia Lehrensang auf dem Argentumturnierplatz.", progress = "Habt Ihr die Eier besorgen können? Diese Würmer werden anfangen, ihre Tierführer zu fressen, wenn sie nicht schon bald gefüttert werden.", completion = "Gut gemacht, {name}. Ich werde diese hier umgehend zu den Tierführern des Argentumkreuzzugs bringen. Sie werden keine andere Wahl haben und anerkennen müssen, dass wir um einiges mehr leisten als die Sonnenhäscher, wenn es darum geht, für den reibungslosen Ablauf im Kolosseum zu sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14077] = { id = 14077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barmherzigkeit des Lichts", description = "Ich habe Beichtpatin Blondlocke aufmerksam gelauscht, und ich sage Euch, ihre Worte gaben mir zu denken. Es genügt nicht, einfach nur an der Seite der Kreuzfahrer zu kämpfen, wir müssen uns ihre Mission zu Eigen machen.\n\nAn der Nordküste liegt Hrothgars Landestelle, wo die seefahrenden Kvaldir eine alte Tuskarrsiedlung überrannt und deren Bewohner getötet haben. Nehmt dieses Buch und lest den Leichen der Dorfbewohner ihre Sterbesakramente. So ermöglicht Ihr ihren Seelen, die Fesseln der Nebel um die Insel abzustreifen und ihren Frieden zu finden.", sourceObjective = "Benutzt das Gebetbuch der Beichtpatin, um 8 erschlagenen Tualiq-Bewohnern ihre Sterbesakramente zu lesen, und kehrt dann zu Narasi Schneedämmerung auf dem Argentumturnierplatz zurück.", progress = "Habt Ihr Euch der Seelen der erschlagenen Tualiq-Bewohner angenommen?", completion = "<Narasi nimmt das Gebetbuch von Euch entgegen.>\n\nIch danke Euch. Dieses Buch war ein Geschenk der Beichtpatin Blondlocke selbst. Sie wäre sicher hocherfreut, dass Ihr es eingesetzt habt, um das Leid der erschlagenen Seelen zu lindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[14079] = { id = 14079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen im Wald von Elwynn", description = "Dieser Handzettel bewirbt das bei Randal Waidmann erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nRandal Waidmann befindet sich im Holzfällerlager des Osttals im Wald von Elwynn, von Sturmwind aus östlich die Straße entlang.", sourceObjective = "Bringt diesen Handzettel zu Randal Waidmann beim Holzfällerlager des Osttals im Wald von Elwynn.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14080] = { id = 14080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einhalt den Aggressoren", description = "Die Kvaldir, räuberische Vrykul, die überall Angst und Schrecken verbreiten, haben unsere Lieferungen abgefangen und sämtliche Tuskarrbewohner einer Insel im Norden ermordet. Sie haben die Insel bereits in Hrothgars Landestelle umbenannt. Wenn es ihnen gelingt, dort langfristig Fuß zu fassen, werden wir mit Sicherheit zu ihrem nächsten Ziel.\n\nDie Streitkräfte des Kreuzzugs haben jedoch alle Hände voll zu tun mit der Geißel, und wir müssen den Turnierplatz beschützen. Fliegt vom Platz aus Richtung Norden, bis Ihr die Insel erreicht und nehmt Euch der Kvaldir an, bevor sie noch mehr zerstören können!", sourceObjective = "Narasi Schneedämmerung auf dem Argentumturnierplatz möchte, dass Ihr 10 Kvaldir tötet.", completion = "Eure Taten haben bewiesen, dass wir Schulter an Schulter mit dem Argentumkreuzzug stehen, während die Sonnenhäscher zu viel Zeit mit Herumstolzieren verschwenden, um noch zu den Waffen greifen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[14081] = { id = 14081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen im Immersangwald", description = "Dieser Handzettel bewirbt das bei Perascamin erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nPerascamin befindet sich bei Thurons Aufzucht, südöstlich des Hirtentors außerhalb von Silbermond.", sourceObjective = "Bringt diesen Handzettel zu Perascamin bei Turons Aufzucht in Silbermond.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14082] = { id = 14082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in der Exodar", description = "Dieser Handzettel bewirbt das bei Aalun erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nAalun befindet sich am Eingang zur Exodar auf der Azurmythosinsel.", sourceObjective = "Bringt diesen Handzettel zu Aalun außerhalb der Exodar auf der Azurmythosinsel.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14083] = { id = 14083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Dun Morogh", description = "Dieser Handzettel bewirbt das bei Ultham Eisenhorn erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nUltham Eisenhorn befindet sich im Gehöft Bernruh in Dun Morogh, von Eisenschmiede aus östlich die Straße entlang.", sourceObjective = "Bringt diesen Handzettel zu Ultham Eisenhorn beim Gehöft Bernruh in Dun Morogh.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14084] = { id = 14084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Dun Morogh", description = "Dieser Handzettel bewirbt das bei Binjy Federpfiff erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nBinjy Federpfiff befindet sich bei Stahlrosts Depot, direkt nordöstlich von Kharanos in Dun Morogh.", sourceObjective = "Bringt diesen Handzettel zu Binjy Federpfiff bei Stahlrosts Depot in Dun Morogh.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14085] = { id = 14085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Darnassus", description = "Dieser Handzettel bewirbt das bei Jartsam erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nJartsam befindet sich in der Enklave des Cenarius in Darnassus.", sourceObjective = "Bringt diesen Handzettel zu Jartsam bei der Enklave des Cenarius in Darnassus.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14086] = { id = 14086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Orgrimmar", description = "Dieser Handzettel bewirbt das bei Kildar erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nKildar befindet sich im Tal der Ehre in Orgrimmar.", sourceObjective = "Bringt diesen Handzettel zu Kildar im Tal der Ehre in Orgrimmar.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14087] = { id = 14087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Mulgore", description = "Dieser Handzettel bewirbt das bei Kar Sturmsang erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nKar Sturmsang befindet sich im Dorf der Bluthufe in Mulgore.", sourceObjective = "Bringt diesen Handzettel zu Kar Sturmsang beim Dorf der Bluthufe in Mulgore.", sourceObjectiveStatus = "unverified-source-field" }
quests[14088] = { id = 14088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Durotar", description = "Dieser Handzettel bewirbt das bei Xar'Ti erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nXar'Ti befindet sich in Sen'jin in Durotar.", sourceObjective = "Bringt diesen Handzettel zu Xar'Ti in Sen'jin im südlichen Durotar.", progress = "Ah, Ihr habt meinen Brief erhalten? Gut.", completion = "Also, wollt Ihr mit Euren Reitstunden anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14089] = { id = 14089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten lernen in Tirisfal", description = "Dieser Handzettel bewirbt das bei Velma Warnam erhältliche Reittraining und Angebote zum Erwerb von Reittieren.\n\nVelma Warnam befindet sich in Brill in Tirisfal.", sourceObjective = "Bringt diesen Handzettel zu Velma Warnam in Brill in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[14090] = { id = 14090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok will seine Schneebolde", description = "Zwei meiner Männer kamen schon bei dem Versuch um, den Magnatauren namens Gormok den Pfähler einzusperren, doch die Kreatur treibt noch immer ihr Unwesen. Sie heult und jammert stundenlang darüber, dass ihr Lieblingsschneebold nicht da ist.\n\nIch würde sie mit eigenen Händen töten, wenn der Argentumkreuzzug dieses Monster nicht ins Kolosseum schicken wollte. Vielleicht ist es an der Zeit, der Bestie ihr Spielzeug zu bringen. Hier, nehmt dieses Netz und begebt Euch nach Garms Bann im Südosten der Sturmgipfel gleich nordöstlich von K3. Fangt ein paar dieser Schneebolde und betet zum Licht, dass Ihr den richtigen gefunden habt.", sourceObjective = "Fangt mithilfe des beschwerten Netzes 8 schneeblinde Anhänger und bringt sie zu Savinia Lehrensang auf dem Argentumturnierplatz.", completion = "Je eher diese stinkenden Dinger aus meinen Augen verschwinden und in ihren Käfigen landen, um so schneller wird sich meine Stimmung bessern. Ich wünschte, der Argentumkreuzzug hätte den Sonnenhäschern die Aufsicht über diese Kreatur gegeben. Sie sind sich so ähnlich, dass sie sich eigentlich verstehen sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14092] = { id = 14092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühstück der Champions", description = "Nun, da das Kolosseum fertiggestellt ist, haben wir vom Argentumkreuzzug die Bitte erhalten, bei der Pflege der Kreaturen zu helfen, die als Gegner für die Champions dienen werden.\n\nDie riesigen Jormungar ernähren sich womöglich auf die seltsamste Art und Weise: Sie wachsen heran, indem sie die Eier ihrer eigenen Artgenossen fressen, und die besten Eier stammen von den Tiefenjormungar.\n\nNehmt diese Trommel und begebt Euch in die Fußmarschen im Zentrum der Sturmgipfel. Spielt sie anschließend in der Nähe der Schneehügel, die Ihr dort seht. Ihr Ton wird die Tiefenjormungar aufscheuchen. Tötet sie, sammelt ihre Eiersäcke ein und bringt sie zurück zum Turnierplatz.", sourceObjective = "Beschafft Euch 4 Eiersäcke eines Jormungars und bringt sie zu Tylos Dämmerflucht auf dem Argentumturnierplatz.", progress = "Habt Ihr die Eier besorgen können? Die Jormungar werden unausstehlich, wenn man sie nicht füttert.", completion = "Ich werde die Kreuzfahrer wissen lassen, dass Ihr gerade eine Ladung frisches Futter zurückgebracht habt, während der Silberbund faul herumsitzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14095] = { id = 14095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überreste identifizieren", description = "Ein ganzer Zahn eines toten Kraken ist in der Tat ein seltener Fund. Kreuzfahrer Silberdämmerung wird das sehen wollen.", sourceObjective = "Bringt den Krakenzahn zum Beweis Eures Sieges zu Kreuzfahrer Silberdämmerung.", sourceObjectiveStatus = "unverified-source-field" }
quests[14096] = { id = 14096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diesmal habt Ihr Euch wirklich selbst übertroffen, Kul", description = "Kreuzfahrer Kul hat sich mal wieder in Schwierigkeiten gebracht, nur dieses Mal hat er noch andere mit hineingezogen. Als er sah, wie Kultisten in Todessprechers Wacht westlich des Turnierplatzes ihr Lager aufschlugen, rief er die Streiter für einen Angriff zusammen.\n\nOhne Verstärkung wurden Kul und seine Gefolgschaft schnell gefangengenommen. Ich habe keine Zweifel, dass der Kult die Gefangenen opfern wird - es sei denn, wir können einen Rettungseinsatz in Gang bringen. Jeder von diesen Kultisten könnte Schlüssel für die schwarzen Käfige bei sich haben. Findet die Schlüssel und befreit Kul und die gefangenen Streiter.", sourceObjective = "Rettet Kul den Tollkühnen und 4 gefangene Streiter aus Todessprechers Wacht und kehrt dann zu Narasi Schneedämmerung auf dem Argentumturnierplatz zurück.", completion = "Dank Euch haben Kul und die Streiter überlebt, um weiterhin die Geißel zu bekämpfen. Das ist bei Weitem nicht das erste Mal, dass jemand Kul vor sich selbst retten musste. Ich hoffe nur, dass die Kreuzfahrer ein besseres Ventil für seinen Enthusiasmus finden, als ihm weiter zu gestatten, seine schlechten Angewohnheiten an junge und noch beeindruckbare Streiter weiterzugeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[14100] = { id = 14100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikt des Irdenen Rings", description = "Ihr seid weit in Eurem Training vorangekommen, {name}. Nun, da Ihr die vier grundlegenden Elemente voll und ganz beherrscht, müsst Ihr Euch darum bemühen, alle vier im Gleichgewicht zu halten. Diese Disziplin hat einen praktischen Vorteil: Mit etwas Übung könnt Ihr nur ein einziges Relikt tragen anstatt alle vier Totems.\n\nSprecht mit Gotura Vierwind im Tal der Weisheit in Orgrimmar und feilt an Eurer Beherrschung der Elemente.", sourceObjective = "Bringt Eure vier Totems nach Orgrimmar zu Gotura Vierwind.", progress = "Hmmm, was verleitet Euch, die Hilfe des Irdenen Rings zu suchen?", completion = "Ah, Ihr beherrscht nun die vier Totems. Ihr solltet stolz auf das sein, was Ihr bisher erreicht habt, junger {race}, aber das ist lediglich der Anfang Eurer Reise.\n\nHier, akzeptiert dies als Geschenk des Irdenen Rings. Tragt dieses Relikt bei Euch und die Macht aller vier Elemente wird Euch zu Diensten stehen.\n\nFührt Euer Training weiter. Diese Welt hat noch Schlimmes vor sich - ich kann es im Wind hören und fühle es im Rumpeln der Erde. Wir müssen auf das Schlimmste vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[14101] = { id = 14101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drottinn Hrothgar", description = "Die Kvaldir, seefahrende Vrykul, die Schiffe und Küstensiedlungen überfallen, haben eine Tuskarrinsel auf der anderen Seite der Meerenge gen Norden überrannt. Ihr Anführer ist ein altgedienter Plünderer namens Drottinn Hrothgar, der die Kontrolle über diesen Teil der See erlangen möchte.\n\nMit ihm an der Macht werden unsere Lieferungen und Truppentransporter niemals sicher sein. Wir werden hier gestrandet und dem Lichkönig auf Gedeih und Verderb ausgeliefert sein.\n\nHier, bringt dieses erbeutete Kriegshorn der Kvaldir zum Tuskarrstatuenkreis im nordöstlichen Teil von Hrothgars Landestelle und verwendet es, um den Anführer der Kvaldir herauszufordern.", sourceObjective = "Hochmeister Adelard auf dem Argentumturniergelände möchte, dass Ihr Drottinn Hrothgar besiegt.", completion = "Die Niederlage von Drottinn Hrothgar wird die Kvaldir gegeneinander aufhetzen, was uns genug Zeit verschafft, unseren Vorteil zu nutzen. Der Kreuzzug und das Turnier stehen in unserer Schuld, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[14102] = { id = 14102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelrufer Yngvar", description = "Die Kvaldir sind zur Küste von Nordend zurückgekehrt und wenn sich niemand um sie kümmert, werden sie verhindern, dass Vorräte und Verstärkung hier ankommen. Einer von ihnen, bekannt als Nebelrufer Yngvar, hat sich in einer Höhle auf der Westseite von Hrothgars Landestelle eingenistet. Von dort aus beeinflusst er den Nebel, um die Kvaldir und deren Meeresbestien zu verbergen.\n\nHier, nehmt diesen Glücksbringer und überquert die Meerenge nördlich des Turnierplatzes in Richtung Hrothgars Landestelle. Findet die Höhle des Nebelrufers und bringt ihn mithilfe des Glücksbringers zum Vorschein.", sourceObjective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Nebelrufer Yngvar tötet.", completion = "Ihr habt uns kostbare Zeit verschafft, um gegen die Kvaldir vorzurücken und das Meer von diesen Quälgeistern zu befreien. Der Argentumkreuzzug steht einmal mehr in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[14103] = { id = 14103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanstaub", progress = "Hallo, {name}! Habt Ihr was zum Handeln?", completion = "Wunderbar! Noch eine Ladung Pulver!\n\nUnter uns Juwelenschleifern, ich habe bei den Magiern von Dalaran ein Riesengeschäft mit Schmuck aus \"reinem Titanium\" gemacht. Selbst mit ihrem überragenden Verstand sind sie nicht schlau genug, was Ihr Gold angeht. Ich bin hier, falls Ihr noch mehr bekommen solltet." }
quests[14104] = { id = 14104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ornolf der Vernarbte", description = "Ornolf der Vernarbte gilt als angsteinflößender Plünderer und ist unter seinen Kvaldirbrüdern bekannt dafür, Schiffe zu plündern und zu kapern. Vom Schiff Bors Zorn aus greifen seine Mannschaft und er unsere Schiffe an und stehlen unsere Ladung.\n\nOrnolf und seine Männer gehören zu denjenigen, die Mord an den Einwohnern einer Tuskarrinsel begangen haben und diese in Hrothgars Landestelle umbenannten. Sein Schiff liegt am östlichen Ende des Hafens der Insel vor Anker. Nehmt diesen erbeuteten Banner an Euch und stellt ihn auf diesem Schiff auf, um ihn zu provozieren und in den Kampf mit Euch zu locken.", sourceObjective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Ornolf den Vernarbten tötet.", completion = "Ornolfs Mannschaft wird Ihren Anführer rächen wollen, aber ohne ihn werden sie einfacher zu besiegen sein. Wir haben unser Leben der Aufgabe geweiht, die Eiskrone von der Geißel und anderem Bösen zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[14105] = { id = 14105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todessprecher Kharos", description = "Der Kult der Verdammten hat seine Anstrengungen verdoppelt, um unsere Vernichtung herbeizuführen. Sie sind mutig geworden und sammeln in Todessprechers Wacht auf dem Gebirgskamm westlich des Turnierplatzes ihre Kräfte.\n\nDer erbarmungslose Todessprecher Kharos hat seinen Männern befohlen, ihre Stellungen zu befestigen, um sich darauf vorzubereiten, alle Waffen des Kults einzusetzen.\n\nMeine Männer bereiten sich und die Recken darauf vor, den Platz zu verteidigen - ich möchte jedoch, dass Champions wie Ihr, {name}, unsere Streitkräfte anführen, um den Angriff abzuschwächen. Findet Todessprecher Kharos und tötet ihn.", sourceObjective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Todessprecher Kharos tötet.", completion = "Wahrhaftig, Ihr seid ein Beispiel für alle, die sich unter unserem Banner versammelt haben, {name}. Gemeinsam werden wir der Geißel zeigen, dass wir nicht in die Knie gezwungen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14106] = { id = 14106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Na Kada's Questtest" }
quests[14107] = { id = 14107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Gefallenen", description = "Der Argentumkreuzzug ist wohl kaum die erste Streitmacht, die den Lichkönig herausfordert. Unser Feind hetzt die Geister der Gefallenen gegen uns auf.\n\nSie streifen im Tal der Gefallenen Helden südwestlich des Platzes zwischen Aldur'thar und dem Eisenwallbollwerk umher. Die Gegend ist mit weggeworfenen Seelenkristallen, mit denen die Geißel die Geister kontrolliert, übersät. Sammelt diese Seelenkristalle und verwendet sie gemeinsam mit diesem lichtgesegneten Relikt, um den Geistern den Segen des Friedens zu verleihen. Sie haben ihre Ruhe mehr als verdient.", sourceObjective = "Kreuzfahrer Silberdämmerung möchte, dass Ihr dafür sorgt, dass 6 Geister der gefallenen Helden Frieden finden.", completion = "Ihr habt unseren gefallenen Brüdern einen großen Dienst erwiesen und es uns erspart, ihnen erneut auf dem Schlachtfeld begegnen zu müssen. Mit dem Voranschreiten der Kampagne gegen die Geißel ertappe ich mich dabei, über mein eigenes Schicksal nachzusinnen.\n\nSollte ich fallen, {name}, würde ich wollen, dass Ihr dasselbe für mich tätet wie an diesem heutigen Tage für die Geister der Gefallenen. Ich könnte den Gedanken nicht ertragen, meinen eigenen Bruder dazu zu zwingen, mich immer wieder zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14108] = { id = 14108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kraken am Haken", description = "Die Sonnenhäscher und der Silberbund haben Schiffe nach Norden entsandt, um die Kvaldir bei Hrothgars Landestelle anzugreifen, jedoch wurden sie von einem Seeräuberschiff der Kvaldir abgefangen und anschließend gefangen genommen. Was die Sache noch schlimmer macht, ist, dass die Kvaldir einen Weg gefunden haben, den gefürchteten Kraken aus den Tiefen des Nordmeeres hervorzurufen. Wenn irgendjemand an Bord da lebend herauskommen soll, muss der Kraken weggejagt und das Beschwörungsritual der Kvaldir... unterbrochen werden.\n\nHier <Kreuzfahrer/Kreuzfahrerin>, nehmt diese Speere. Ein Argentumhippogryph wird Euch in die Schlacht tragen.", sourceObjective = "Kreuzfahrer Silberdämmerung möchte, dass Ihr auf einen Argentumhippogryph steigt, 6 flammende Speere auf den Nordmeerkraken werft und 3 Tiefenrufer der Kvaldir ausschaltet.\n\nIhr findet die Argentumhippogryphen gleich außerhalb des Zelts auf dem Argentumturnierplatz.", progress = "Habt Ihr den Kraken schon verjagt? Beeilt Euch, Kreuzfahrer! Es bleibt nicht viel Zeit.", completion = "Kreuzfahrer, Ihr habt den Seemännern womöglich gerade genug Zeit verschafft, um ihre Flucht zu ermöglichen. Vielleicht werden die Leute vom Silberbund und die Sonnenhäscher das nächste Mal hinhören, bevor sie sich Hals über Kopf auf den Feind stürzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14111] = { id = 14111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikt des Irdenen Rings", description = "Ihr seid weit in Eurem Training vorangekommen, {name}. Nun, da Ihr die vier grundlegenden Elemente voll und ganz beherrscht, müsst Ihr Euch darum bemühen, alle vier im Gleichgewicht zu halten. Diese Disziplin hat einen praktischen Vorteil: Mit etwas Übung könnt Ihr nur ein einziges Relikt tragen anstatt alle vier Totems.\n\nSprecht mit Weitseher Eannu in der Nähe der großen Schmiede in Eisenschmiede. Er wird Euch dabei helfen, Eure Beherrschung der Elemente zu verfeinern.", sourceObjective = "Bringt Eure vier Totems nach Eisenschmiede zu Weitseher Eannu.", progress = "In Euch regen sich die Geister. Was bringt Euch dazu, die Hilfe des Irdenen Rings zu suchen?", completion = "Wie ich sehe, beherrscht Ihr nun den Gebrauch der vier Totems. Ihr seid auf dem Weg, eins mit den elementaren Geistern zu werden - aber dies ist erst der Anfang Eurer Reise.\n\nHier, akzeptiert dies als Geschenk des Irdenen Rings. Tragt dieses Relikt bei Euch und die Macht aller vier Elemente wird Euch zu Diensten stehen.\n\nEuer Training muss weitergehen! Ich spüre, dass diese Welt sehr viele Prüfungen erwarten, und wir werden die Macht der Elemente hinter uns wissen müssen, wenn wir die Oberhand gewinnen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14112] = { id = 14112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was fressen eigentlich Yetis?", description = "Die Kreuzfahrer haben einen Yeti eingefangen, den sie Eisheuler nennen. Er soll an den Kämpfen im Kolosseum teilnehmen und man hat uns gebeten, bei Training und Unterhalt zu helfen.\n\nDie Kreuzfahrer waren nicht begeistert von meinem Vorschlag, der Bestie überschüssige Sonnenhäscher zum Fressen zu geben. Die Kreatur hat eine Vorliebe für Haifischfleisch, also will ich, dass Ihr zur Silberklinge hinunterfliegt, die in der Meerenge gen Norden schwimmt. Besorgt Euch ein wenig frischen Köder aus einem der Kübel auf dem Boot und schüttet ihn ins Wasser, um Haie damit anzulocken.", sourceObjective = "Savinia Lehrensang auf dem Argentumturnierplatz möchte, dass Ihr ihr 3 Stück Fleisch eines Nordmeerhais bringt.", progress = "Ich hoffe, dass Ihr etwas habt, mit dem ich Eisheuler füttern kann, sonst werde ich wirklich damit anfangen, Sonnenhäscher in seinen Käfig zu schmeißen.", completion = "Ich bin froh, dass wir das geschafft haben. Es ist zwar nicht die glanzvollste Aufgabe, aber als wir uns mit dem Argentumkreuzzug zusammengetan haben, versprachen wir, ohne Murren alles zu tun, was sie von uns verlangen. Natürlich kann man dasselbe nicht von den Sonnenhäschern behaupten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14136] = { id = 14136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungseinsatz auf See", description = "Die Kvaldir haben auf Hrothgars Landestelle, der kleinen Insel im Norden, ihr Lager aufgeschlagen. Wir haben Kapitän Aerthas Feuerfalke in die Gegend geschickt, aber er und seine Mannschaft sind auf eine Seeräuberbande der Kvaldir gestoßen, die in Richtung Turnierplatz unterwegs war! Nun wird die Feuerfalke von den Seeräubern angegriffen und ihre Mannschaft ist weit in der Unterzahl. Geht dort hinaus und zeigt diesen Kvaldir, weshalb es keine gute Idee ist, die Sonnenhäscher anzugreifen.\n\nDie Feuerfalke befindet sich zwischen Hrothgars Landestelle im Norden und dem Turnierplatz, auf der westlichen Seite der Straße der Meerhäscher.", sourceObjective = "Girana die Blutgezeichnete auf dem Argentumturnierplatz möchte, dass Ihr 8 Berserker der Kvaldir und 3 Harpunierer der Kvaldir an Bord der Feuerfalke tötet.", completion = "Gute Arbeit, Champion. Der Kampf geht weiter, aber nun wissen die Kvaldir, dass wir solche Angriffe nicht dulden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14140] = { id = 14140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einhalt den Aggressoren", description = "Die Kvaldir, räuberische Vrykul, die überall Angst und Schrecken verbreiten, haben unsere Lieferungen abgefangen und sämtliche Tuskarrbewohner einer Insel im Norden ermordet. Sie haben die Insel bereits in Hrothgars Landestelle umbenannt. Wenn es ihnen gelingt, dort langfristig Fuß zu fassen, werden wir mit Sicherheit zu ihrem nächsten Ziel.\n\nDie Streitkräfte des Kreuzzugs haben jedoch alle Hände voll zu tun mit der Geißel, und wir müssen den Turnierplatz beschützen. Fliegt vom Platz aus Richtung Norden, bis Ihr die Insel erreicht und nehmt Euch der Kvaldir an, bevor sie noch mehr zerstören können!", sourceObjective = "Girana die Blutgezeichnete auf dem Argentumturnierplatz möchte, dass Ihr 10 Kvaldir tötet.", completion = "Eure Taten haben bewiesen, dass wir Sonnenhäscher dem Argentumkreuzzug um einiges bessere Verbündete sind als der Silberbund, und dass wir es sein werden, die am Ende triumphieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[14141] = { id = 14141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok will seine Schneebolde", description = "Zwei meiner Männer kamen schon bei dem Versuch um, den Magnatauren namens Gormok den Pfähler einzusperren, doch die Kreatur treibt noch immer ihr Unwesen. Sie heult und jammert stundenlang darüber, dass ihr Lieblingsschneebold nicht da ist.\n\nIch würde sie mit eigenen Händen töten, wenn der Argentumkreuzzug dieses Monster nicht ins Kolosseum schicken wollte. Vielleicht ist es an der Zeit, der Bestie ihr Spielzeug zu bringen. Hier, nehmt dieses Netz und begebt Euch nach Garms Bann im Südosten der Sturmgipfel gleich nordöstlich von K3. Fangt ein paar dieser Schneebolde und betet zum Licht, dass Ihr den richtigen gefunden habt.", sourceObjective = "Fangt mithilfe des beschwerten Netzes 8 schneeblinde Anhänger und bringt sie zu Tylos Dämmerflucht auf dem Argentumturnierplatz.", completion = "Je eher diese stinkenden Dinger aus meinen Augen verschwinden und in ihren Käfigen landen, um so schneller wird sich meine Stimmung bessern. Ich wünschte, der Argentumkreuzzug hätte dem Silberbund die Aufsicht über diese Kreatur gegeben. Die werden sich die Hände schmutzig machen müssen, wenn die Schlacht um die Zitadelle beginnt, und ich habe das Gefühl, dass sie sich als schwache und zimperliche Verbündete erweisen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14142] = { id = 14142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diesmal habt Ihr Euch wirklich selbst übertroffen, Kul", description = "Kreuzfahrer Kul hat sich mal wieder in Schwierigkeiten gebracht, nur dieses Mal hat er noch andere mit hineingezogen. Als er sah, wie Kultisten in Todessprechers Wacht westlich des Turnierplatzes ihr Lager aufschlugen, rief er die Streiter für einen Angriff zusammen.\n\nSie wurden mit Leichtigkeit gefangen genommen und nun schmachtet Kul in einem Käfig auf der Plattform im Lager. Ich bin mir sicher, dass der Kult die Gefangenen opfern wird - es sei denn, wir können sie retten. Jeder von diesen Kultisten könnte Schlüssel für die schwarzen Käfige bei sich haben. Findet die Schlüssel und befreit Kul und die gefangenen Streiter.", sourceObjective = "Rettet Kul den Tollkühnen und 4 gefangene Streiter aus Todessprechers Wacht und kehrt dann zu Girana der Blutgezeichneten auf dem Argentumturnierplatz zurück.", completion = "Kul wird weiterleben und sich wieder lächerlich machen. Und es ist keinesfalls das erste Mal, dass jemand Kul vor sich selbst retten musste. Es sind solche Beispiele, bei denen es einen nicht wundert, dass die meisten Streiter die Gewohnheiten des Silberbunds annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14143] = { id = 14143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legt mal ein Bein zu", description = "Der Argentumkreuzzug hatte ein schnelles Schiff mit einer Ladung Weitschreiterfleisch und weiteren Vorräten entsendet, die für uns hier am Turnierplatz vorgesehen waren, doch nie eingetroffen sind. Späher berichteten uns von einem Angriff der Kvaldir, räuberische Vrykul, die Angst und Schrecken auf den Meeren verbreiten.\n\nSie haben die Crew erschlagen und die Ladung auf eine Insel namens Hrothgars Landestelle gebracht. Wenn Ihr Richtung Norden blickt, könnt Ihr sie schemenhaft erkennen, verborgen im Nebel. Würdet Ihr uns helfen, das Diebesgut zurückzubeschaffen? Ohne diese Weitschreiterbeine werden wir bald hungern müssen.", sourceObjective = "Beschafft 10 gestohlene Weitschreiterbeine zurück und bringt sie zu Girana der Blutgezeichneten auf dem Argentumturnierplatz.", progress = "Konntet Ihr die gestohlenen Vorräte wiederbeschaffen?", completion = "Sie sehen etwas mitgenommen aus, doch sie sind noch immer genießbar. Die Kreuzzügler werden es gerne hören, dass wir ein wenig Erfolg hatten. Vielleicht können wir die leicht vergammelten Stücke dem Silberbund geben. Das würde mir den Tag versüßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14144] = { id = 14144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barmherzigkeit des Lichts", description = "Ich habe Beichtpatin Blondlocke aufmerksam gelauscht, und ich sage Euch, ihre Worte gaben mir zu denken. Zwar kämpfen wir Seite an Seite mit den Kreuzfahrern, aber wir könnten auch von ihnen lernen.\n\nAn der Nordküste liegt Hrothgars Landestelle, wo die seefahrenden Kvaldir eine alte Tuskarrsiedlung überrannt und deren Bewohner getötet haben. Nehmt dieses Buch und lest den Leichen der Dorfbewohner ihre Sterbesakramente. So ermöglicht Ihr ihren Seelen, die Fesseln der Nebel um die Insel abzustreifen und ihren Frieden zu finden.", sourceObjective = "Benutzt das Gebetbuch der Beichtpatin, um 8 erschlagenen Tualiq-Bewohnern ihre Sterbesakramente zu lesen, und kehrt dann zu Girana der Blutgezeichneten auf dem Argentumturnierplatz zurück.", progress = "Habt Ihr Euch der Seelen der erschlagenen Tualiq-Bewohner angenommen?", completion = "<Girana nimmt das Gebetbuch von Euch entgegen.>\n\nIch danke Euch. Wir sind vielleicht nicht immer einer Meinung mit den Kreuzfahrern, aber ich habe in meiner Zeit hier viel von Beichtpatin Blondlocke gelernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14145] = { id = 14145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was fressen eigentlich Yetis?", description = "Die Kreuzfahrer haben einen Yeti eingefangen, den sie Eisheuler nennen. Er soll an den Kämpfen im Kolosseum teilnehmen und man hat uns gebeten, bei Training und Unterhalt zu helfen.\n\nDie Kreuzfahrer waren nicht begeistert von meinem Vorschlag, ein paar Mitglieder des Silberbundes an die Bestie zu verfüttern. Die Kreatur hat eine Vorliebe für Haifischfleisch, also will ich, dass Ihr zum Schiff \"Scharlachroter Morgen\" hinunterfliegt, das in der Meerenge gen Norden schwimmt. Besorgt Euch ein wenig frischen Köder aus einem der Kübel auf dem Boot und schüttet ihn ins Wasser, um Haie damit anzulocken.", sourceObjective = "Tylos Dämmerflucht auf dem Argentumturnierplatz möchte, dass Ihr ihm 3 Stück Fleisch eines Nordmeerhais bringt.", progress = "Ich hoffe, dass Ihr etwas habt, mit dem ich Eisheuler füttern kann, sonst werde ich wirklich damit anfangen, Mitglieder des Silberbunds in seinen Käfig zu schmeißen.", completion = "Ich bin froh, dass wir das geschafft haben. Es ist zwar nicht die glanzvollste Aufgabe, aber als wir uns mit dem Argentumkreuzzug zusammengetan haben, versprachen wir, ohne Murren alles zu tun, was sie von uns verlangen. Natürlich kann man dasselbe nicht vom Silberbund behaupten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14151] = { id = 14151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kardinalsrubin", description = "Man sagt, dass der Kardinalsrubin der feinste Edelstein in ganz Nordend ist. Er funkelt wie eine Kristallrose in der Sonne.\n\nBevor ich Euch die Herstellung beibringe, bitte ich Euch, fünf Transmutationen epischer Edelsteine durchzuführen, um auf diese Weise Euren Geist vorzubereiten. Welche Transmutationen Ihr wählt, das liegt an Euch. Ihr könnt auch mehrmals dieselbe durchführen.\n\nKehrt zu mir zurück, wenn Ihr wirklich bereit seid.", sourceObjective = "Linzy Schwarzbolz in Dalaran möchte, dass Ihr 5 erfolgreiche Transmutationen epischer Edelsteine mithilfe Eurer Alchemiefertigkeit durchführt. Für die Transmutation akzeptable Edelsteine sind Ametrine, Augen von Zul, Schreckenssteine, Königsbernsteine und Fürstenzirkone.", completion = "Sehr gut, {name}.\n\nDer Trick bei der Sache ist nun, die Ausrichtung der Facetten gerade richtig hinzubekommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[14152] = { id = 14152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungseinsatz auf See", description = "Champion, Kapitänin Schaumkrone und ihr Schiff wurden nach Norden entsandt, um die Kvaldir bei Hrothgars Landestelle zu behelligen, als sie von einer Seeräuberbande der Kvaldir abgefangen wurden, die in Richtung Turnierplatz unterwegs war! Unglücklicherweise sind die Kvaldir der Mannschaft an Bord zahlenmäßig um einiges überlegen und gerade dabei, das Schiff zu übernehmen.\n\nIhr müsst Euch auf nach Norden zur Schaumkrone machen, die sich in der Straße der Meerhäscher zwischen dem Turnierplatz und Hrothgars Landestelle befindet, und der Mannschaft helfen, den Angriff abzuwehren. Das Schiff sollte sich auf der Ostseite der Meeresenge befinden.", sourceObjective = "Begebt Euch in Richtung des Nordmeers und tötet unter den Angreifern der Schaumkrone 8 Berserker der Vrykul und 3 Harpunierer der Vrykul.", completion = "Es scheint, als wären die Dinge schlimmer, wie anfangs gedacht. Ihr habt noch immer Tapferkeit gezeigt und dabei viele Besatzungsmitglieder der Schaumkrone gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14160] = { id = 14160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leistungsurkunde", description = "Auf diesem feinen Pergament befindet sich eine Liste mit einer großen Anzahl an Leistungen, die {name} in der Tradition des Juwelenschleifens errungen hat.\n\nBringt diese Urkunde zu Jonas Timotheus nach Dalaran zurück, um eine angemessene Belohnung zu erhalten.", sourceObjective = "Liefert die Leistungsurkunde bei Jonas Timotheus in Dalaran ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[14163] = { id = 14163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen: Insel der Eroberung", description = "Da wir dem Sieg in Eiskrone immer näher kommen, ist es deutlicher geworden, dass sich unsere Armeen mit der Horde auseinandersetzen müssen, bevor sie sich um den Lichkönig kümmern können.\n\nSie haben die Elitewache bekannt als die Kor'kron eingesetzt, um unseren Vormarsch auf der Insel der Eroberung aufzuhalten. Die Insel ist von äußerst wichtiger strategischer Bedeutung, {name}. Seht zu, dass unsere Jungs gewinnen!", sourceObjective = "Erringt den Sieg bei einer Partie auf dem Schlachtfeld \"Insel der Eroberung\" und kehrt zu einem Brigadegeneral der Allianz in irgendeiner Hauptstadt, Dalaran oder Shattrath zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[14164] = { id = 14164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen: Insel der Eroberung", description = "Der Sieg in Nordend wird bald unser sein... doch nicht bevor wir in Eiskrone Fuß gefasst haben, um für den Transport und die Versorgung unserer Truppen zu sorgen.\n\nDie Insel der Eroberung ist ein idealer Ort. Sie ist einfach zu verteidigen und reich an Ressourcen. Die Allianz ist zu demselben Schluss gelangt und hat die 7. Legion ausgesandt, um unseren Streitkräften die Kontrolle zu entreißen.\n\nGeht, {name}, und sorgt dafür, dass die Horde um jeden Preis die Oberhand gewinnt!", sourceObjective = "Erringt den Sieg bei einer Partie auf dem Schlachtfeld \"Insel der Eroberung\" und kehrt zu einem Kriegshetzer der Horde in irgendeiner Hauptstadt, Dalaran oder Shattrath zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[14166] = { id = 14166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Geist aus Dalaran auf dem Friedhof von Dalaran.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14167] = { id = 14167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Zwergengeist auf dem Friedhof von Eisenschmiede.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14168] = { id = 14168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Gnomengeist auf dem Friedhof von Eisenschmiede.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14169] = { id = 14169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Draeneigeist auf dem Friedhof der Exodar.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
