quests[14176] = { id = 14176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Taurengeist auf dem Friedhof von Donnerfels.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14177] = { id = 14177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Trollgeist auf dem Friedhof von Orgrimmar.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14178] = { id = 14178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Die Realität eines Kampfes an mehreren Fronten ist, dass wir unsere Streitkräfte nicht zu dünn verteilen dürfen, sonst riskieren wir nämlich alles zu verlieren!\n\nVon Tag zu Tag sind äußerst wichtige Truppeneinsätze vonnöten. Heute sind es unsere Streitkräfte in der Schlacht im Arathibecken, die umgehend Verstärkung benötigen.\n\nBringt mir die Siegesnachricht, {name}. Wir können dem Abschaum der Horde nicht erlauben, jene Ressourcen zu sichern, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Das sind gute Neuigkeiten, {class}! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14179] = { id = 14179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Auge des Sturms", description = "Der Kampf gegen die Horde kennt keine Grenzen, {name}. Selbst in der Scherbenwelt reichen territoriale Zwistigkeiten und alte Feindschaften aus, um das Gleichgewicht zu stören und Krieg hervorzurufen.\n\nBegebt Euch ins Auge des Sturms und stellt sicher, dass die Allianz in der Scherbenwelt die Oberhand gewinnt, genauso wie sie es in Azeroth getan hat.", sourceObjective = "Gewinnt eine Schlacht im Auge des Sturms und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Wir sind dem endgültigen Sieg über die Horde wieder einen Schritt näher gekommen. Niemals dürfen wir zulassen, dass der Feind sich einen Brückenkopf in dieser oder in irgendeiner anderen Welt sichert.", sourceObjectiveStatus = "unverified-source-field" }
